/* HK4 · Đất nước học Trung Quốc: đoạn giáo trình gốc + bài tập nâng cao. */
(function (C) {
  var hk4 = null; C.semesters.forEach(function (s) { if (s.id === 'hk4') hk4 = s; });
  hk4.lessons = hk4.lessons.concat([{"id": "hk4-l12", "no": 12, "day": "HK4 · Đất nước học 1", "time": "09:00", "scene": "hall", "room": "hall", "cast": ["prof", "edward", "zhangdong", "tianfang"], "vi": "Giáo dục Trung Quốc cổ đại", "zh": "中国古代教育", "py": "Zhōngguó gǔdài jiàoyù", "shop": {"label": "科举博物馆", "sub": "Bảo tàng khoa cử", "icon": "🏛️"}, "vocab": [["培养", "Péiyǎng", "bồi dưỡng", ""], ["素质", "Sùzhì", "tố chất", ""], ["重视", "Zhòngshì", "coi trọng", ""], ["官学", "Guānxué", "quan học (trường nhà nước)", ""], ["私学", "Sīxué", "tư học (trường tư)", ""], ["诸侯", "Zhūhóu", "chư hầu", ""], ["朝代", "Cháodài", "triều đại", ""], ["儒家", "Rújiā", "Nho gia", ""], ["教材", "Jiàocái", "giáo trình", ""], ["科举制度", "Kējǔzhìdù", "chế độ khoa cử", ""], ["选拔", "Xuǎnbá", "tuyển chọn", ""], ["官吏", "Guānlì", "quan lại", ""], ["阶梯", "Jiētī", "nấc thang", ""], ["消极", "Xiāojí", "tiêu cực", ""], ["创始人", "Chuàngshǐrén", "người sáng lập", ""], ["有教无类", "Yǒujiàowúlèi", "dạy học không phân biệt", ""], ["财富", "Cáifù", "tài sản, của cải", ""], ["书院", "Shūyuàn", "thư viện (học viện xưa)", ""], ["盛行", "Shèngxíng", "thịnh hành", ""], ["载体", "Zàitǐ", "vật mang", ""], ["公平", "Gōngpíng", "công bằng", ""], ["统治阶级", "Tǒngzhìjiējí", "giai cấp thống trị", ""], ["黄金时代", "Huángjīnshídài", "thời kỳ hoàng kim", ""]], "story": [{"c": "panda", "vi": "Đất nước học · Giáo dục Trung Quốc cổ đại. Đọc đoạn giáo trình gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "edward", "zh": "教育在一个国家中占有重要地位，它关系到人才的培养和国民素质的提高，关系到科学、文化及整个社会的发展，所以，各个国家各个时代的政府，一般都重视教育。中国的教育历史悠久，内容丰富，不但从教育学的角度上值得研究，而且也是认识中国所需要了解的一个方面。", "py": "Jiàoyù zài yíge guójiā zhōng zhànyǒu zhòngyào dìwèi, tā guānxi dào réncái de péiyǎng hé guómínsùzhì de tígāo, guānxi dào kēxué, wénhuà jí zhěngge shèhuì de fāzhǎn, suǒyǐ, gège guójiā gège shídài de zhèngfǔ, yìbān dōu zhòngshì jiàoyù. Zhōngguó de jiàoyù lìshǐyōujiǔ, nèiróngfēngfù, búdàn cóng jiàoyùxué de jiǎodù shàng zhíde yánjiū, érqiě yě shì rènshi zhōngguó suǒ xūyào liǎojiě de yíge fāngmiàn.", "vi": "Giáo dục giữ vị trí quan trọng trong một quốc gia, nó liên quan đến việc bồi dưỡng nhân tài và nâng cao tố chất người dân, liên quan đến sự phát triển của khoa học, văn hóa và cả xã hội, vì vậy chính phủ các nước ở mọi thời đại nói chung đều coi trọng giáo dục. Giáo dục Trung Quốc có lịch sử lâu đời, nội dung phong phú, không những đáng nghiên cứu từ góc độ giáo dục học mà còn là một mặt cần tìm hiểu để hiểu Trung Quốc."}, {"c": "prof", "zh": "为什么各个国家的政府一般都重视教育？", "py": "Wèishénme gège guójiā de zhèngfǔ yìbān dōu zhòngshì jiàoyù?", "vi": "Vì sao chính phủ các nước đều coi trọng giáo dục?"}, {"me": "Vì giáo dục liên quan đến nhân tài, tố chất người dân và sự phát triển xã hội.", "opts": [["因为教育关系到人才培养、国民素质和整个社会的发展。", "Yīnwèi jiàoyù guānxi dào réncáipéiyǎng, guómínsùzhì hé zhěngge shèhuì de fāzhǎn.", "Vì giáo dục liên quan đến nhân tài, tố chất người dân và sự phát triển xã hội."], ["因为教育可以赚很多钱。", "Yīnwèi jiàoyù kěyǐ zhuàn hěnduō qián.", "(chưa đúng với bài)"], ["因为老师要求政府重视。", "Yīnwèi lǎoshī yāoqiú zhèngfǔ zhòngshì.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "官学建立于西周时期，是指政府开办和管理的学校，分作“国学”、“乡学”两种。“国学”设在周王朝和各诸侯国的国都，是中央设立的学校，有“大学”和“小学”之分。小学设在王宫南边左侧，大学则设在国都的南郊。“乡学”设在地方。", "py": "Guānxué jiànlì yú xīzhōushíqī, shì zhǐ zhèngfǔ kāibàn hé guǎnlǐ de xuéxiào, fēn zuò “Guóxué”, “Xiāngxué” liǎngzhǒng. “Guóxué” shèzài zhōu wángcháo hé gè zhūhóuguó de guó dōu, shì zhōngyāng shèlì de xuéxiào, yǒu “Dàxué” hé “Xiǎoxué” zhīfēn. Xiǎoxué shèzài wánggōng nánbian zuǒcè, dàxué zé shèzài guódū de nánjiāo. “Xiāngxué” shèzài dìfāng.", "vi": "Quan học được lập từ thời Tây Chu, là trường học do nhà nước mở và quản lý, chia làm hai loại “quốc học” và “hương học”. “Quốc học” đặt ở kinh đô của nhà Chu và các nước chư hầu, là trường do trung ương lập, chia ra “đại học” và “tiểu học”. Tiểu học đặt bên trái phía nam vương cung, đại học đặt ở ngoại ô phía nam kinh đô. “Hương học” đặt ở địa phương."}, {"c": "prof", "zh": "“国学”和“乡学”有什么不同？", "py": "“Guóxué” hé “Xiāngxué” yǒu shénme bùtóng?", "vi": "“Quốc học” và “hương học” khác nhau thế nào?"}, {"me": "Quốc học ở kinh đô do trung ương lập; hương học ở địa phương.", "opts": [["国学设在国都，是中央设立的；乡学设在地方。", "Guóxué shèzài guódū, shì zhōngyāng shèlì de; xiāngxué shèzài dìfāng.", "Quốc học ở kinh đô do trung ương lập; hương học ở địa phương."], ["国学是私人开的，乡学是政府开的。", "Guóxué shì sīrén kāi de, xiāngxué shì zhèngfǔ kāi de.", "(chưa đúng với bài)"], ["国学只教音乐，乡学只教数学。", "Guóxué zhǐjiào yīnyuè, xiāngxué zhǐjiào shùxué.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "秦代以后，几乎各个朝代都设立了中央官学和地方官学，有专门担任教师的官吏，以儒家著作作为基本教材。不过，由于从隋代以后中国实行了科举制度，即通过考试选拔官吏，所以，后来的官学完全服从于科举制度，成了当官的阶梯。科举制度在体现社会公正的同时，对教育本身的发展带来了长期的消极的影响。", "py": "Qíndài yǐhòu, jīhū gège cháodài dōu shèlì le zhōngyāng guānxué hé dìfāngguān xué, yǒu zhuānmén dānrèn jiàoshī de guānlì, yǐ rújiā zhùzuò zuòwéi jīběn jiàocái. Búguò, yóuyú cóng suídài yǐhòu zhōngguó shíxíng le kējǔzhìdù, jí tōngguò kǎoshì xuǎnbá guānlì, suǒyǐ, hòulái de guānxué wánquán fúcóng yú kējǔzhìdù, chéng le dāngguān de jiētī. Kējǔzhìdù zài tǐxiàn shèhuì gōngzhèng de tóngshí, duì jiàoyù běnshēn de fāzhǎn dàilái le chángqī de xiāojí de yǐngxiǎng.", "vi": "Từ sau đời Tần, hầu như triều đại nào cũng lập quan học trung ương và địa phương, có quan lại chuyên làm thầy, lấy sách Nho gia làm giáo trình cơ bản. Tuy nhiên, vì từ đời Tùy về sau Trung Quốc thực hiện chế độ khoa cử, tức tuyển chọn quan lại qua thi cử, nên quan học về sau hoàn toàn phục tùng khoa cử, trở thành nấc thang để làm quan. Chế độ khoa cử vừa thể hiện sự công bằng xã hội, đồng thời cũng mang lại ảnh hưởng tiêu cực lâu dài cho bản thân sự phát triển của giáo dục."}, {"c": "prof", "zh": "科举制度对官学有什么影响？", "py": "Kējǔzhìdù duì guānxué yǒu shénme yǐngxiǎng?", "vi": "Khoa cử ảnh hưởng gì đến quan học?"}, {"me": "Quan học phục tùng khoa cử, thành nấc thang làm quan.", "opts": [["官学完全服从于科举，成了当官的阶梯。", "Guānxué wánquán fúcóng yú kējǔ, chéng le dāngguān de jiētī.", "Quan học phục tùng khoa cử, thành nấc thang làm quan."], ["官学都被取消了。", "Guānxué dōu bèi qǔxiāo le.", "(chưa đúng với bài)"], ["官学开始教外语。", "Guānxué kāishǐ jiào wàiyǔ.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "西周以前，只有官学，没有私学，所以大多数普通家庭的孩子受教育的机会不多。进入春秋时代，儒学的创始人孔子首开个人讲学之风，提出“有教无类”的主张，不分贵族平民都可以入学。孔子教育思想和教育实践是中国文化、中国教育的宝贵财富，据说弟子达三千人。于是，中国古代产生了新的办学形式——私学。", "py": "Xīzhōu yǐqián, zhǐyǒu guānxué, méiyǒu sīxué, suǒyǐ dàduōshù pǔtōngjiātíng de háizi shòu jiàoyù de jīhuì bù duō. Jìnrù chūnqiūshídài, rúxué de chuàngshǐrén kǒngzi shǒukāi gerén jiǎngxué zhīfēng, tíchū “Yǒujiàowúlèi” de zhǔzhāng, bù fēn guìzú píngmín dōu kěyǐ rùxué. Kǒngzi jiàoyù sīxiǎng hé jiàoyù shíjiàn shì zhōngguó wénhuà, zhōngguó jiàoyù de bǎoguìcáifù, jùshuō dìzǐ dá sānqiān rén. Yúshì, zhōngguó gǔdài chǎnshēng le xīn de bànxué xíngshì—— sīxué.", "vi": "Trước Tây Chu chỉ có quan học, không có tư học, nên phần lớn con em gia đình bình thường ít có cơ hội được học. Sang thời Xuân Thu, Khổng Tử – người sáng lập Nho học – mở đầu phong trào dạy học tư nhân, đề ra chủ trương “hữu giáo vô loại”, không phân quý tộc hay bình dân đều được vào học. Tư tưởng và thực tiễn giáo dục của Khổng Tử là tài sản quý của văn hóa, giáo dục Trung Quốc; nghe nói học trò lên tới ba nghìn người. Thế là Trung Quốc cổ đại có một hình thức mở trường mới – tư học."}, {"c": "prof", "zh": "孔子提出了什么教育主张？", "py": "Kǒngzi tíchū le shénme jiàoyù zhǔzhāng?", "vi": "Khổng Tử đề ra chủ trương giáo dục gì?"}, {"me": "“Hữu giáo vô loại”, quý tộc hay bình dân đều được học.", "opts": [["“有教无类”，贵族平民都可以入学。", "“Yǒujiàowúlèi”, guìzú píngmín dōu kěyǐ rùxué.", "“Hữu giáo vô loại”, quý tộc hay bình dân đều được học."], ["只有贵族可以读书。", "Zhǐyǒu guìzú kěyǐ dúshū.", "(chưa đúng với bài)"], ["学生必须先考试。", "Xuéshēng bìxū xiān kǎoshì.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "书院是中国封建教育的一种特殊形式，历时一千余年，其管理制度及教学方式跟国子监与太学等有很大区别，在教育史上产生过重要的影响。书院开始于唐代，盛行于宋代，被誉为“中华优秀传统文化的重要源头和载体”，有官办和私办两种。", "py": "Shūyuàn shì zhōngguó fēngjiàn jiàoyù de yìzhǒng tèshū xíngshì, lìshí yìqiānyúnián, qí guǎnlǐzhìdù jí jiàoxuéfāngshì gēn guózǐjiàn yǔ tàixué děng yǒu hěndà qūbié, zài jiàoyùshǐ shàng chǎnshēng guò zhòngyào de yǐngxiǎng. Shūyuàn kāishǐ yú tángdài, shèngxíngyú sòngdài, bèiyùwéi “Zhōnghuá yōuxiù chuántǒng wénhuà de zhòngyào yuántóu hé zàitǐ”, yǒu guānbàn hé sībàn liǎngzhǒng.", "vi": "Thư viện (thư viện học đường) là một hình thức đặc biệt của giáo dục phong kiến Trung Quốc, kéo dài hơn một nghìn năm, chế độ quản lý và cách dạy khác nhiều với Quốc Tử Giám và Thái học, có ảnh hưởng quan trọng trong lịch sử giáo dục. Thư viện bắt đầu từ đời Đường, thịnh hành đời Tống, được ca ngợi là “nguồn gốc và vật mang quan trọng của văn hóa truyền thống ưu tú Trung Hoa”, có hai loại công lập và tư lập."}, {"c": "prof", "zh": "书院开始于哪个朝代？盛行于哪个朝代？", "py": "Shūyuàn kāishǐ yú nǎge cháodài? Shèngxíngyú nǎge cháodài?", "vi": "Thư viện bắt đầu và thịnh hành vào triều đại nào?"}, {"me": "Bắt đầu đời Đường, thịnh đời Tống.", "opts": [["开始于唐代，盛行于宋代。", "Kāishǐ yú tángdài, shèngxíngyú sòngdài.", "Bắt đầu đời Đường, thịnh đời Tống."], ["开始于清代，盛行于明代。", "Kāishǐ yú qīngdài, shèngxíngyú míngdài.", "(chưa đúng với bài)"], ["开始于汉代，盛行于秦代。", "Kāishǐ yú hàndài, shèngxíngyú qíndài.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "科举制度是封建时代所能采取的最公平的人才选拔形式，它扩展了封建国家引进人才的社会层面，吸收了大量出身中下层社会的人士进入统治阶级。特别是唐宋时期，科举制度之初，显示出生气勃勃的进步性，形成了中国古代文化发展的一个黄金时代。", "py": "Kējǔzhìdù shì fēngjiànshídài suǒ néng cǎiqǔ de zuì gōngpíng de réncái xuǎnbá xíngshì, tā kuòzhǎn le fēngjiàn guójiā yǐnjìnréncái de shèhuì céngmiàn, xīshōu le dàliàng chūshēn zhōngxiàcéng shèhuì de rénshì jìnrù tǒngzhìjiējí. Tèbié shì tángsòng shíqī, kējǔzhìdù zhīchū, xiǎnshì chū shēngqìbóbó de jìnbùxìng, xíngchéng le zhōngguó gǔdài wénhuà fāzhǎn de yíge huángjīnshídài.", "vi": "Chế độ khoa cử là hình thức tuyển chọn nhân tài công bằng nhất mà thời phong kiến có thể áp dụng, nó mở rộng tầng lớp xã hội mà nhà nước phong kiến thu nạp nhân tài, đưa nhiều người xuất thân tầng lớp trung và dưới vào giai cấp thống trị. Nhất là thời Đường Tống, buổi đầu chế độ khoa cử thể hiện tính tiến bộ đầy sức sống, tạo nên một thời kỳ hoàng kim của văn hóa cổ đại Trung Quốc."}, {"c": "prof", "zh": "作者为什么说科举是“最公平的人才选拔形式”？", "py": "Zuòzhě wèishénme shuō kējǔ shì “Zuì gōngpíng de réncái xuǎnbá xíngshì”?", "vi": "Vì sao nói khoa cử là cách tuyển nhân tài công bằng nhất?"}, {"me": "Nó cho nhiều người tầng lớp dưới vào giai cấp thống trị qua thi cử.", "opts": [["它让大量中下层社会的人通过考试进入统治阶级。", "Tā ràng dàliàng zhōngxiàcéng shèhuì de rén tōngguò kǎoshì jìnrù tǒngzhìjiējí.", "Nó cho nhiều người tầng lớp dưới vào giai cấp thống trị qua thi cử."], ["因为考试题目很简单。", "Yīnwèi kǎoshì tímù hěn jiǎndān.", "(chưa đúng với bài)"], ["因为只有皇帝的孩子能参加。", "Yīnwèi zhǐyǒu huángdì de háizi néng cānjiā.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "不但……而且……", "d": "Không những… mà còn….", "ex": [["中国教育不但值得研究，而且也是认识中国需要了解的一个方面。", "Zhōngguó jiàoyù búdàn zhíde yánjiū, érqiě yě shì rènshi zhōngguó xūyào liǎojiě de yíge fāngmiàn.", "Giáo dục TQ không những đáng nghiên cứu mà còn là mặt cần tìm hiểu."]]}, {"t": "由……担任", "d": "Do… đảm nhiệm.", "ex": [["教师由国家公务人员担任。", "Jiàoshī yóu guójiā gōngwùrényuán dānrèn.", "Giáo viên do công chức nhà nước đảm nhiệm."]]}, {"t": "以……作为……", "d": "Lấy… làm….", "ex": [["官学以儒家著作作为基本教材。", "Guānxuéyǐ rújiā zhùzuò zuòwéi jīběn jiàocái.", "Quan học lấy sách Nho gia làm giáo trình cơ bản."]]}, {"t": "在……的同时", "d": "Đồng thời với…, trong khi….", "ex": [["科举制度在体现社会公正的同时，也带来了消极的影响。", "Kējǔzhìdù zài tǐxiàn shèhuì gōngzhèng de tóngshí, yě dàilái le xiāojí de yǐngxiǎng.", "Khoa cử vừa thể hiện công bằng, đồng thời cũng mang ảnh hưởng tiêu cực."]]}, {"t": "被誉为……", "d": "Được ca ngợi là….", "ex": [["书院被誉为“中华优秀传统文化的重要源头”。", "Shūyuàn bèiyùwéi “Zhōnghuá yōuxiù chuántǒng wénhuà de zhòngyào yuántóu”.", "Thư viện được ca ngợi là nguồn gốc quan trọng của văn hóa truyền thống."]]}], "order": [], "u": {"gq": [{"s": "不但……而且……", "d": "Không những… mà còn….", "ok": "中国教育不但值得研究，而且也是认识中国需要了解的一个方面。", "vi": "Giáo dục TQ không những đáng nghiên cứu mà còn là mặt cần tìm hiểu.", "bad": ["中国教育不但值得研究，但是也是认识中国需要了解的一个方面。", "不但中国教育值得研究，而且也而且是一个方面。"]}, {"s": "由……担任", "d": "Do… đảm nhiệm.", "ok": "教师由国家公务人员担任。", "vi": "Giáo viên do công chức nhà nước đảm nhiệm.", "bad": ["教师担任由国家公务人员。", "教师由国家公务人员被担任。"]}, {"s": "以……作为……", "d": "Lấy… làm….", "ok": "官学以儒家著作作为基本教材。", "vi": "Quan học lấy sách Nho gia làm giáo trình cơ bản.", "bad": ["官学作为儒家著作以基本教材。", "官学以儒家著作基本教材作为了。"]}, {"s": "在……的同时", "d": "Đồng thời với…, trong khi….", "ok": "科举制度在体现社会公正的同时，也带来了消极的影响。", "vi": "Khoa cử vừa thể hiện công bằng, đồng thời cũng mang ảnh hưởng tiêu cực.", "bad": ["科举制度在体现社会公正同时的，也带来了消极的影响。", "科举制度在的同时体现社会公正，也带来了消极的影响。"]}, {"s": "被誉为……", "d": "Được ca ngợi là….", "ok": "书院被誉为“中华优秀传统文化的重要源头”。", "vi": "Thư viện được ca ngợi là nguồn gốc quan trọng của văn hóa truyền thống.", "bad": ["书院誉为被“中华优秀传统文化的重要源头”。", "书院被“中华优秀传统文化的重要源头”誉为了吗。"]}], "disc": [{"q": "越南古代也有科举制度。你觉得考试是选拔人才的好方法吗？", "py": "Yuènán gǔdài yě yǒu kējǔzhìdù. Nǐ juéde kǎoshì shì xuǎnbá réncái de hǎo fāngfǎ ma?", "vi": "Việt Nam xưa cũng có khoa cử. Bạn thấy thi cử có phải cách tốt để chọn nhân tài?", "keys": ["在……的同时", "不但……而且|不但……也", "以……作为|以……为"], "sample": "越南的科举一直到1919年才结束。我觉得考试比较公平，它不但给普通人机会，而且能选出有知识的人。但是在体现公平的同时，只以考试成绩作为标准也有缺点。", "spy": "Yuènán de kējǔ yìzhí dào1919 nián cái jiéshù. Wǒ juéde kǎoshì bǐjiào gōngpíng, tā búdàn gěi pǔtōngrén jīhuì, érqiě néng xuǎnchū yǒu zhīshí de rén. Dànshì zài tǐxiàn gōngpíng de tóngshí, zhǐyǐ kǎoshìchéngjì zuòwéi biāozhǔn yě yǒu quēdiǎn."}], "comp": [{"vi": "Trường này lấy tiếng Trung làm ngôn ngữ giảng dạy. (以……作为……)", "keys": ["以", "作为|为"], "model": "这所学校以汉语作为教学语言。", "mpy": "Zhèsuǒ xuéxiào yǐ hànyǔ zuòwéi jiàoxué yǔyán."}, {"vi": "Hội Gióng được ca ngợi là di sản văn hóa của nhân loại. (被誉为)", "keys": ["被誉为"], "model": "这个节日被誉为人类的文化遗产。", "mpy": "Zhège jiérì bèiyùwéi rénlèi de wénhuàyíchǎn."}, {"vi": "Học tiếng Trung không những thú vị mà còn hữu ích. (不但……而且……)", "keys": ["不但", "而且|也"], "model": "学汉语不但有意思，而且很有用。", "mpy": "Xué hànyǔ búdàn yǒu yìsi, érqiě hěn yǒuyòng."}], "ex": [{"q": "为什么各个国家的政府一般都重视教育？", "qvi": "Vì sao chính phủ các nước đều coi trọng giáo dục?", "a": "因为教育关系到人才培养、国民素质和整个社会的发展。", "avi": "Vì giáo dục liên quan đến nhân tài, tố chất người dân và sự phát triển xã hội.", "bad": ["因为教育可以赚很多钱。", "因为老师要求政府重视。"], "p": 0}, {"q": "“国学”和“乡学”有什么不同？", "qvi": "“Quốc học” và “hương học” khác nhau thế nào?", "a": "国学设在国都，是中央设立的；乡学设在地方。", "avi": "Quốc học ở kinh đô do trung ương lập; hương học ở địa phương.", "bad": ["国学是私人开的，乡学是政府开的。", "国学只教音乐，乡学只教数学。"], "p": 1}, {"q": "科举制度对官学有什么影响？", "qvi": "Khoa cử ảnh hưởng gì đến quan học?", "a": "官学完全服从于科举，成了当官的阶梯。", "avi": "Quan học phục tùng khoa cử, thành nấc thang làm quan.", "bad": ["官学都被取消了。", "官学开始教外语。"], "p": 2}, {"q": "孔子提出了什么教育主张？", "qvi": "Khổng Tử đề ra chủ trương giáo dục gì?", "a": "“有教无类”，贵族平民都可以入学。", "avi": "“Hữu giáo vô loại”, quý tộc hay bình dân đều được học.", "bad": ["只有贵族可以读书。", "学生必须先考试。"], "p": 3}, {"q": "书院开始于哪个朝代？盛行于哪个朝代？", "qvi": "Thư viện bắt đầu và thịnh hành vào triều đại nào?", "a": "开始于唐代，盛行于宋代。", "avi": "Bắt đầu đời Đường, thịnh đời Tống.", "bad": ["开始于清代，盛行于明代。", "开始于汉代，盛行于秦代。"], "p": 4}, {"q": "作者为什么说科举是“最公平的人才选拔形式”？", "qvi": "Vì sao nói khoa cử là cách tuyển nhân tài công bằng nhất?", "a": "它让大量中下层社会的人通过考试进入统治阶级。", "avi": "Nó cho nhiều người tầng lớp dưới vào giai cấp thống trị qua thi cử.", "bad": ["因为考试题目很简单。", "因为只有皇帝的孩子能参加。"], "p": 5}]}}, {"id": "hk4-l13", "no": 13, "day": "HK4 · Đất nước học 2", "time": "14:30", "scene": "library", "room": "library", "cast": ["prof", "lee", "roland", "tianfang"], "vi": "Khổng Tử và Nho gia", "zh": "孔子与儒家", "py": "Kǒngzi yǔ rújiā", "shop": {"label": "儒学书院", "sub": "Thư viện Nho học", "icon": "📜"}, "vocab": [["没落", "Mòluò", "sa sút", ""], ["贫困", "Pínkùn", "nghèo khó", ""], ["刻苦", "Kèkǔ", "khắc khổ, chăm chỉ", ""], ["虚心", "Xūxīn", "khiêm tốn, hư tâm", ""], ["请教", "Qǐngjiào", "thỉnh giáo, hỏi", ""], ["广博", "Guǎngbó", "uyên bác", ""], ["创办", "Chuàngbàn", "sáng lập, mở", ""], ["治理", "Zhìlǐ", "cai trị, quản lý", ""], ["昏庸", "Hūnyōng", "hôn ám, u mê", ""], ["周游", "Zhōuyóu", "chu du", ""], ["诸侯国", "Zhūhóuguó", "nước chư hầu", ""], ["宣传", "Xuānchuán", "tuyên truyền", ""], ["主张", "Zhǔzhāng", "chủ trương", ""], ["奔走", "Bēnzǒu", "bôn ba", ""], ["整理", "Zhěnglǐ", "chỉnh lý", ""], ["修订", "Xiūdìng", "sửa chữa, hiệu đính", ""], ["贡献", "Gòngxiàn", "cống hiến", ""], ["思想家", "Sīxiǎngjiā", "nhà tư tưởng", ""], ["教育家", "Jiàoyùjiā", "nhà giáo dục", ""], ["温文尔雅", "Wēnwéněryǎ", "ôn hòa nho nhã", ""], ["继承", "Jìchéng", "kế thừa", ""], ["流派", "Liúpài", "trường phái", ""], ["独尊", "Dúzūn", "độc tôn", ""]], "story": [{"c": "panda", "vi": "Đất nước học · Khổng Tử và Nho gia. Đọc đoạn giáo trình gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "lee", "zh": "公元前551年，孔子出生在鲁国陬邑（今山东曲阜）的一个没落贵族家庭。孔子3岁时，他的父亲就死了，后来母亲也去世了。孔子的少年时代是贫困的，他管理过仓库，也看管过牛羊，这些工作他做得都十分出色。他很喜欢读书，为了将来能为国家出力，他认真地学习礼、乐、射、御、书、数六艺。孔子学习刻苦而又虚心，有不懂的事情就向别人请教。他学习礼，就到很远的洛邑（今洛阳），请教学问很大的老子。他在齐国听到古代音乐的演奏，就专心学习，竟然达到“三月不知肉味”的程度。这样，孔子逐渐成为学问广博的学者。那时候，很多读书人愿拜孔子作老师，于是，孔子就创办了私学。", "py": "Gōngyuánqián551 nián, kǒngzi chūshēng zài lǔguó zōu yì (Jīn shāndōng qūfù) de yíge mòluò guìzú jiātíng. Kǒngzi3 suì shí, tā de fùqīn jiù sǐ le, hòulái mǔqīn yě qùshì le. Kǒngzi de shàoniánshídài shì pínkùn de, tā guǎnlǐ guò cāngkù, yě kānguǎn guò niúyáng, zhèxiē gōngzuò tā zuò dé dōu shífēn chūsè. Tā hěn xǐhuan dúshū, wèile jiānglái néngwèi guójiā chūlì, tā rènzhēn dì xuéxí lǐ, lè, shè, yù, shū, shù liùyì. Kǒngzi xuéxí kèkǔ ér yòu xūxīn, yǒu bù dǒng de shìqing jiù xiàng biérén qǐngjiào. Tā xuéxí lǐ, jiù dào hěn yuǎn de luòyì (Jīn luòyáng), qǐngjiào xuéwen hěndà de lǎozi. Tā zài qíguó tīngdào gǔdài yīnyuè de yǎnzòu, jiù zhuānxīn xuéxí, jìngrán dádào “Sān yuè bù zhī ròu wèi” de chéngdù. Zhèyàng, kǒngzi zhújiàn chéngwéi xuéwen guǎngbó de xuézhě. Nà shíhou, hěnduō dúshūrén yuànbài kǒngzi zuò lǎoshī, yúshì, kǒngzi jiù chuàngbàn le sīxué.", "vi": "Năm 551 TCN, Khổng Tử sinh ra trong một gia đình quý tộc sa sút ở ấp Trâu nước Lỗ (nay là Khúc Phụ, Sơn Đông). Năm Khổng Tử 3 tuổi, cha ông mất, sau đó mẹ cũng qua đời. Thời niên thiếu ông nghèo khó, từng trông kho, chăn bò dê, việc nào cũng làm rất tốt. Ông rất thích đọc sách; để sau này góp sức cho đất nước, ông chăm chỉ học sáu nghề lễ, nhạc, xạ, ngự, thư, số. Khổng Tử học hành khắc khổ mà khiêm tốn, có gì không hiểu thì hỏi người khác. Học lễ, ông đến tận Lạc Ấp xa xôi hỏi Lão Tử uyên bác. Ở nước Tề nghe tấu nhạc cổ, ông chuyên tâm học đến mức “ba tháng không biết vị thịt”. Cứ thế Khổng Tử dần thành học giả uyên bác. Khi ấy nhiều người đọc sách muốn bái ông làm thầy, nên ông mở trường tư."}, {"c": "prof", "zh": "孔子少年时代的生活怎么样？", "py": "Kǒngzi shàoniánshídài de shēnghuó zěnmeyàng?", "vi": "Thời niên thiếu Khổng Tử sống thế nào?"}, {"me": "Nghèo khó, từng trông kho, chăn bò dê.", "opts": [["很贫困，管理过仓库，看管过牛羊。", "Hěn pínkùn, guǎnlǐ guò cāngkù, kānguǎn guò niúyáng.", "Nghèo khó, từng trông kho, chăn bò dê."], ["非常富有，什么都不用做。", "Fēicháng fùyǒu, shénme dōu búyòng zuò.", "(chưa đúng với bài)"], ["一直在宫里当官。", "Yìzhí zài gōnglǐ dāngguān.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "“三月不知肉味”说明了什么？", "py": "“Sān yuè bù zhī ròu wèi” shuōmíng le shénme?", "vi": "“Ba tháng không biết vị thịt” cho thấy điều gì?"}, {"me": "Khổng Tử học nhạc vô cùng chuyên tâm.", "opts": [["孔子学习音乐非常专心。", "Kǒngzi xuéxí yīnyuè fēicháng zhuānxīn.", "Khổng Tử học nhạc vô cùng chuyên tâm."], ["孔子不喜欢吃肉。", "Kǒngzi bù xǐhuan chī ròu.", "(chưa đúng với bài)"], ["孔子家里没有钱买肉。", "Kǒngzi jiālǐ méiyǒu qián mǎi ròu.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "孔子50岁时在鲁国做了官。他当官时间不长，却把鲁国治理得非常好，表现出较好的政治才能。不久，孔子对昏庸的鲁国国君十分失望，就不做官了，带着他的学生周游各个诸侯国，宣传他的政治主张，希望各国的国君能采用他的意见。可是，他辛辛苦苦奔走了十几年，各国国君都不用他，他只好又回到鲁国，那时他已经68岁了。", "py": "Kǒngzi50 suì shí zài lǔguó zuò le guān. Tā dāngguān shíjiān bù zhǎng, què bǎ lǔguó zhìlǐ dé fēicháng hǎo, biǎoxiàn chūjiào hǎo de zhèngzhì cáinéng. Bùjiǔ, kǒngzi duì hūnyōng de lǔguó guójūn shífēn shīwàng, jiù bú zuòguān le, dài zhe tā de xuéshēng zhōuyóu gège zhūhóuguó, xuānchuán tā de zhèngzhì zhǔzhāng, xīwàng gèguó de guójūn néng cǎiyòng tā de yìjiàn. Kěshì, tā xīnxīnkǔkǔ bēnzǒu le shíjǐnián, gèguó guójūn dōu búyòng tā, tā zhǐhǎo yòu huídào lǔguó, nàshí tā yǐjīng68 suì le.", "vi": "Năm 50 tuổi Khổng Tử làm quan ở nước Lỗ. Thời gian làm quan không dài nhưng ông cai trị nước Lỗ rất tốt, thể hiện tài chính trị. Không lâu sau, ông rất thất vọng với vua Lỗ hôn ám, bèn thôi làm quan, dẫn học trò chu du các nước chư hầu, tuyên truyền chủ trương chính trị, mong vua các nước dùng ý kiến của mình. Nhưng ông vất vả bôn ba hơn mười năm, vua các nước đều không dùng ông, đành quay về nước Lỗ, khi ấy ông đã 68 tuổi."}, {"c": "prof", "zh": "孔子为什么不做官了？", "py": "Kǒngzi wèishénme bú zuòguān le?", "vi": "Vì sao Khổng Tử thôi làm quan?"}, {"me": "Ông rất thất vọng với vua Lỗ hôn ám.", "opts": [["他对昏庸的鲁国国君十分失望。", "Tā duì hūnyōng de lǔguó guójūn shífēn shīwàng.", "Ông rất thất vọng với vua Lỗ hôn ám."], ["他年纪太大了。", "Tā niánjì tàidà le.", "(chưa đúng với bài)"], ["他想去做生意。", "Tā xiǎng qù zuòshēngyì.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "孔子晚年仍不停地工作，一方面继续讲学，一方面整理古书。据说，他整理了《诗经》《尚书》等几部书，还对鲁国史书《春秋》作了修订。孔子整理古书，对中国古代文化的保存和传播做出了贡献。", "py": "Kǒngzi wǎnnián réng bùtíng dì gōngzuò, yìfāngmiàn jìxù jiǎngxué, yìfāngmiàn zhěnglǐ gǔshū. Jùshuō, tā zhěnglǐ le «Shījīng» «Shàngshū» děng jǐbù shū, hái duì lǔguó shǐshū «Chūnqiū» zuò le xiūdìng. Kǒngzi zhěnglǐ gǔshū, duì zhōngguó gǔdài wénhuà de bǎocún hé chuánbō zuòchū le gòngxiàn.", "vi": "Về già Khổng Tử vẫn không ngừng làm việc, một mặt tiếp tục dạy học, một mặt chỉnh lý sách cổ. Nghe nói ông chỉnh lý 《Kinh Thi》, 《Thượng Thư》 và sửa chữa sử nước Lỗ 《Xuân Thu》. Việc chỉnh lý sách cổ của Khổng Tử góp phần lưu giữ và truyền bá văn hóa cổ đại Trung Quốc."}, {"c": "prof", "zh": "孔子晚年做了哪些工作？", "py": "Kǒngzi wǎnnián zuò le nǎxiē gōngzuò?", "vi": "Về già Khổng Tử làm gì?"}, {"me": "Tiếp tục dạy học, chỉnh lý Kinh Thi, Thượng Thư.", "opts": [["继续讲学，整理《诗经》《尚书》等古书。", "Jìxù jiǎngxué, zhěnglǐ «Shījīng» «Shàngshū» děng gǔshū.", "Tiếp tục dạy học, chỉnh lý Kinh Thi, Thượng Thư."], ["去国外旅行。", "Qù guówài lǚxíng.", "(chưa đúng với bài)"], ["只在家休息。", "Zhǐ zàijiā xiūxi.", "(chưa đúng với bài)"]]}, {"c": "lee", "zh": "孔子是中国古代的大思想家和大教育家，他为后代留下了非常丰富的文化思想财富，使他在中国文化史和世界文化史上占有极其重要的位置。", "py": "Kǒngzi shì zhōngguó gǔdài de dà sīxiǎngjiā hé dà jiàoyùjiā, tā wèi hòudài liúxià le fēicháng fēngfù de wénhuà sīxiǎng cáifù, shǐ tā zài zhōngguó wénhuàshǐ hé shìjiè wénhuàshǐ shàng zhànyǒu jíqízhòngyào de wèizhì.", "vi": "Khổng Tử là nhà tư tưởng lớn, nhà giáo dục lớn của Trung Quốc cổ đại; ông để lại cho hậu thế tài sản tư tưởng văn hóa vô cùng phong phú, khiến ông giữ vị trí cực kỳ quan trọng trong lịch sử văn hóa Trung Quốc và thế giới."}, {"c": "roland", "zh": "儒家又称儒学、孔孟思想、孔儒思想。所谓“儒”，最早是在奴隶主贵族中掌管道德教化、音乐礼仪的官员。后来，这些人在社会变动中逐渐分化，流落到民间。有的为诸侯执掌礼仪，成文“君子儒”；有的则只能替人办理丧葬祭礼，成为“小人儒”。由于这些人熟悉“诗书礼乐”，待人温文尔雅，其学问和道德都高于常人。到孔子出现以后，因其弟子众多，影响扩大，“儒”就成了孔门弟子的专称，由孔子创立的学说称为“儒学”。后经孟子、荀子等人继承和发展，成为春秋战国时代影响最大的思想流派。到汉武帝时代，儒学被推上独尊地位，指导中国社会生活达数千年。至今仍是有一定生命力的学术流派。", "py": "Rújiā yòuchēng rúxué, kǒngmèng sīxiǎng, kǒngrú sīxiǎng. Suǒwèi “Rú”, zuìzǎo shì zài núlìzhǔ guìzú zhōng zhǎngguǎn dàodé jiàohuà, yīnyuè lǐyí de guānyuán. Hòulái, zhèxiē rén zài shèhuì biàndòng zhōng zhújiàn fēnhuà, liúluò dào mínjiān. Yǒu de wèi zhūhóu zhízhǎng lǐyí, chéngwén “Jūnzǐ rú” ; yǒu de zé zhǐnéng tìrén bànlǐ sāngzàng jìlǐ, chéngwéi “Xiǎorén rú”. Yóuyú zhèxiē rén shúxī “Shīshūlǐyuè”, dàirén wēnwéněryǎ, qí xuéwen hé dàodé dōu gāoyú chángrén. Dào kǒngzi chūxiàn yǐhòu, yīn qí dìzǐ zhòngduō, yǐngxiǎng kuòdà, “Rú” jiù chéng le kǒngmén dìzǐ de zhuānchēng, yóu kǒngzi chuànglì de xuéshuō chēngwéi “Rúxué”. Hòujīng mèngzi, xúnzi děng rén jìchéng hé fāzhǎn, chéngwéi chūnqiūzhànguó shídài yǐngxiǎng zuìdà de sīxiǎng liúpài. Dào hànwǔdì shídài, rúxué bèi tuīshàng dúzūn dìwèi, zhǐdǎo zhōngguó shèhuì shēnghuó dá shùqiānnián. Zhìjīn réng shì yǒu yídìng shēngmìnglì de xuéshù liúpài.", "vi": "Nho gia còn gọi là Nho học, tư tưởng Khổng Mạnh. Cái gọi là “nho” ban đầu là quan lại trong giới quý tộc chủ nô coi việc giáo hóa đạo đức, âm nhạc lễ nghi. Về sau họ phân hóa trong biến động xã hội, lưu lạc vào dân gian. Vì họ thông thạo “Thi Thư Lễ Nhạc”, đối nhân ôn hòa nho nhã, học vấn và đạo đức đều hơn người thường. Khi Khổng Tử xuất hiện, vì học trò đông, ảnh hưởng rộng, “nho” trở thành tên gọi riêng cho học trò cửa Khổng, học thuyết do Khổng Tử sáng lập gọi là “Nho học”. Sau được Mạnh Tử, Tuân Tử kế thừa và phát triển, trở thành trường phái tư tưởng ảnh hưởng lớn nhất thời Xuân Thu Chiến Quốc. Đến thời Hán Vũ Đế, Nho học được đưa lên địa vị độc tôn, chỉ đạo đời sống xã hội Trung Quốc mấy nghìn năm. Đến nay vẫn là trường phái học thuật còn sức sống nhất định."}, {"c": "prof", "zh": "儒学什么时候被推上独尊地位？", "py": "Rúxué shénme shíhou bèi tuīshàng dúzūn dìwèi?", "vi": "Nho học được đưa lên độc tôn khi nào?"}, {"me": "Thời Hán Vũ Đế.", "opts": [["汉武帝时代。", "Hànwǔdì shídài.", "Thời Hán Vũ Đế."], ["唐太宗时代。", "Tángtàizōng shídài.", "(chưa đúng với bài)"], ["春秋时代。", "Chūnqiūshídài.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "为了……", "d": "Để… (mục đích).", "ex": [["为了将来能为国家出力，他认真地学习六艺。", "Wèile jiānglái néngwèi guójiā chūlì, tā rènzhēn dì xuéxí liùyì.", "Để sau này góp sức cho đất nước, ông chăm chỉ học lục nghệ."]]}, {"t": "竟然……", "d": "Thế mà, lại (ngoài dự đoán).", "ex": [["他专心学习，竟然达到“三月不知肉味”的程度。", "Tā zhuānxīn xuéxí, jìngrán dádào “Sān yuè bù zhī ròu wèi” de chéngdù.", "Ông chuyên tâm học đến mức ba tháng không biết vị thịt."]]}, {"t": "一方面……一方面……", "d": "Một mặt… một mặt….", "ex": [["孔子晚年一方面继续讲学，一方面整理古书。", "Kǒngzi wǎnnián yìfāngmiàn jìxù jiǎngxué, yìfāngmiàn zhěnglǐ gǔshū.", "Về già, Khổng Tử một mặt dạy học, một mặt chỉnh lý sách cổ."]]}, {"t": "只好……", "d": "Đành phải….", "ex": [["各国国君都不用他，他只好又回到鲁国。", "Gèguó guójūn dōu búyòng tā, tā zhǐhǎo yòu huídào lǔguó.", "Vua các nước không dùng ông, ông đành quay về nước Lỗ."]]}, {"t": "对……做出贡献", "d": "Góp phần vào….", "ex": [["孔子整理古书，对古代文化的保存做出了贡献。", "Kǒngzi zhěnglǐ gǔshū, duì gǔdài wénhuà de bǎocún zuòchū le gòngxiàn.", "Khổng Tử chỉnh lý sách cổ, góp phần lưu giữ văn hóa cổ."]]}], "order": [], "u": {"gq": [{"s": "为了……", "d": "Để… (mục đích).", "ok": "为了将来能为国家出力，他认真地学习六艺。", "vi": "Để sau này góp sức cho đất nước, ông chăm chỉ học lục nghệ.", "bad": ["为了将来能为国家出力，所以他认真地学习六艺了吗。", "他认真地学习六艺为了，将来能为国家出力。"]}, {"s": "竟然……", "d": "Thế mà, lại (ngoài dự đoán).", "ok": "他专心学习，竟然达到“三月不知肉味”的程度。", "vi": "Ông chuyên tâm học đến mức ba tháng không biết vị thịt.", "bad": ["他专心学习，达到竟然“三月不知肉味”的程度。", "竟然他专心学习达到了程度“三月不知肉味”。"]}, {"s": "一方面……一方面……", "d": "Một mặt… một mặt….", "ok": "孔子晚年一方面继续讲学，一方面整理古书。", "vi": "Về già, Khổng Tử một mặt dạy học, một mặt chỉnh lý sách cổ.", "bad": ["孔子晚年一方面继续讲学，另方面整理古书。", "一方面孔子晚年继续讲学，整理古书一方面。"]}, {"s": "只好……", "d": "Đành phải….", "ok": "各国国君都不用他，他只好又回到鲁国。", "vi": "Vua các nước không dùng ông, ông đành quay về nước Lỗ.", "bad": ["各国国君都不用他，他又只好不回到鲁国。", "各国国君都不用他，只好他又回到鲁国了吗。"]}, {"s": "对……做出贡献", "d": "Góp phần vào….", "ok": "孔子整理古书，对古代文化的保存做出了贡献。", "vi": "Khổng Tử chỉnh lý sách cổ, góp phần lưu giữ văn hóa cổ.", "bad": ["孔子整理古书，做出了贡献对古代文化的保存。", "孔子整理古书，对古代文化的保存贡献做出了。"]}], "disc": [{"q": "儒家思想对越南文化有什么影响？举例说明。", "py": "Rújiāsīxiǎng duì yuènán wénhuà yǒu shénme yǐngxiǎng? Jǔlìshuōmíng.", "vi": "Tư tưởng Nho gia ảnh hưởng thế nào đến văn hóa Việt Nam? Cho ví dụ.", "keys": ["一方面……一方面|一方面……另一方面", "对……产生|对……有", "比如|例如"], "sample": "儒家思想对越南文化有很深的影响。一方面，越南人很重视家庭和孝顺父母，另一方面，越南古代也有文庙和科举。比如河内的文庙就是祭祀孔子的地方。", "spy": "Rújiāsīxiǎng duì yuènán wénhuà yǒu hěn shēn de yǐngxiǎng. Yìfāngmiàn, yuènánrén hěn zhòngshì jiātíng hé xiàoshùnfùmǔ, lìngyìfāngmiàn, yuènán gǔdài yě yǒu wénmiào hé kējǔ. Bǐrú hénèi de wénmiào jiùshì jìsì kǒngzi de dìfāng."}], "comp": [{"vi": "Để thi HSK, tôi ngày nào cũng học từ mới. (为了)", "keys": ["为了"], "model": "为了考HSK，我每天都学生词。", "mpy": "Wèile kǎoHSK, wǒ měitiān dōu xuéshēng cí."}, {"vi": "Hết vé rồi, chúng tôi đành ngày mai đi. (只好)", "keys": ["只好"], "model": "票卖完了，我们只好明天去。", "mpy": "Piào màiwán le, wǒmen zhǐhǎo míngtiān qù."}, {"vi": "Cô ấy một mặt đi làm, một mặt học thạc sĩ. (一方面……一方面……)", "keys": ["一方面", "一方面|另一方面"], "model": "她一方面工作，一方面读硕士。", "mpy": "Tā yìfāngmiàn gōngzuò, yìfāngmiàn dú shuòshì."}], "ex": [{"q": "孔子少年时代的生活怎么样？", "qvi": "Thời niên thiếu Khổng Tử sống thế nào?", "a": "很贫困，管理过仓库，看管过牛羊。", "avi": "Nghèo khó, từng trông kho, chăn bò dê.", "bad": ["非常富有，什么都不用做。", "一直在宫里当官。"], "p": 0}, {"q": "“三月不知肉味”说明了什么？", "qvi": "“Ba tháng không biết vị thịt” cho thấy điều gì?", "a": "孔子学习音乐非常专心。", "avi": "Khổng Tử học nhạc vô cùng chuyên tâm.", "bad": ["孔子不喜欢吃肉。", "孔子家里没有钱买肉。"], "p": 0}, {"q": "孔子为什么不做官了？", "qvi": "Vì sao Khổng Tử thôi làm quan?", "a": "他对昏庸的鲁国国君十分失望。", "avi": "Ông rất thất vọng với vua Lỗ hôn ám.", "bad": ["他年纪太大了。", "他想去做生意。"], "p": 1}, {"q": "孔子晚年做了哪些工作？", "qvi": "Về già Khổng Tử làm gì?", "a": "继续讲学，整理《诗经》《尚书》等古书。", "avi": "Tiếp tục dạy học, chỉnh lý Kinh Thi, Thượng Thư.", "bad": ["去国外旅行。", "只在家休息。"], "p": 2}, {"q": "儒学什么时候被推上独尊地位？", "qvi": "Nho học được đưa lên độc tôn khi nào?", "a": "汉武帝时代。", "avi": "Thời Hán Vũ Đế.", "bad": ["唐太宗时代。", "春秋时代。"], "p": 4}]}}, {"id": "hk4-l14", "no": 14, "day": "HK4 · Đất nước học 3", "time": "18:00", "scene": "kitchen", "room": "kitchen", "cast": ["prof", "mom", "meimei", "dad"], "vi": "Lễ tết truyền thống Trung Quốc", "zh": "中国传统节日", "py": "Zhōngguó chuántǒngjiérì", "shop": {"label": "月饼店", "sub": "Tiệm bánh trung thu", "icon": "🥮"}, "vocab": [["农历", "Nónglì", "âm lịch", ""], ["隆重", "Lóngzhòng", "long trọng", ""], ["团聚", "Tuánjù", "đoàn tụ", ""], ["除夕", "Chúxī", "đêm giao thừa", ""], ["除旧布新", "Chújiùbùxīn", "bỏ cũ đón mới", ""], ["饺子", "Jiǎozi", "sủi cảo", ""], ["年糕", "Niángāo", "bánh tổ, bánh năm mới", ""], ["寓意", "Yùyì", "ngụ ý", ""], ["元宵节", "Yuánxiāojié", "Tết Nguyên Tiêu", ""], ["赏灯", "Shǎngdēng", "ngắm đèn", ""], ["俗语", "Súyǔ", "tục ngữ", ""], ["端午节", "Duānwǔjié", "Tết Đoan Ngọ", ""], ["粽子", "Zòngzi", "bánh ú", ""], ["糯米", "Nuòmǐ", "gạo nếp", ""], ["屈原", "Qūyuán", "Khuất Nguyên", ""], ["崇敬", "Chóngjìng", "kính trọng", ""], ["由来", "Yóu lái", "nguồn gốc", ""], ["中秋节", "Zhōngqiūjié", "Tết Trung Thu", ""], ["团圆", "Tuányuán", "đoàn viên", ""], ["思念", "Sīniàn", "nhớ nhung", ""], ["月饼", "Yuèbǐng", "bánh trung thu", ""], ["重阳节", "Chóngyángjié", "Tết Trùng Dương", ""], ["敬老", "Jìnglǎo", "kính lão", ""], ["内涵", "Nèihán", "nội hàm", ""]], "story": [{"c": "panda", "vi": "Đất nước học · Lễ tết truyền thống Trung Quốc. Đọc đoạn giáo trình gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "mom", "zh": "春节也就是农历新年正月初一，是民间最古老最隆重的传统节日。中国人把过春节叫“过年”。", "py": "Chūnjié yě jiùshì nónglì xīnnián zhēngyuèchūyī, shì mínjiān zuì gǔlǎo zuì lóngzhòng de chuántǒngjiérì. Zhōngguó rén bǎ guò chūnjié jiào “Guònián”.", "vi": "Tết Xuân chính là mồng Một tháng Giêng năm mới âm lịch, là ngày lễ truyền thống cổ xưa và long trọng nhất trong dân gian. Người Trung Quốc gọi ăn Tết là “qua năm”."}, {"c": "prof", "zh": "中国人把过春节叫什么？", "py": "Zhōngguó rén bǎ guò chūnjié jiào shénme?", "vi": "Người Trung Quốc gọi ăn Tết là gì?"}, {"me": "Gọi là “qua năm”.", "opts": [["叫“过年”。", "Jiào “Guònián”.", "Gọi là “qua năm”."], ["叫“过节日”。", "Jiào “Guò jiérì”.", "(chưa đúng với bài)"], ["叫“元宵”。", "Jiào “Yuánxiāo”.", "(chưa đúng với bài)"]]}, {"c": "meimei", "zh": "春节是全家团聚的日子。春节前一天的晚上叫“除夕”，就是除旧布新的意思。除夕零点，也就是子时，人们要吃除夕晚上包好的饺子，这就是取“更岁交子”的意思。“交子”就是旧的一年的子时与新的一年的子时相交的时刻。“饺子”的名称就由此得来。除了吃饺子之外还吃年糕、馄饨，取“一年比一年高”和“结束新旧交替的混沌状态”的寓意。", "py": "Chūnjié shì quánjiā tuánjù de rìzi. Chūnjié qiányìtiān de wǎnshang jiào “Chúxī”, jiùshì chújiùbùxīn de yìsi. Chúxī língdiǎn, yě jiùshì zishí, rénmen yào chī chúxī wǎnshang bāohǎo de jiǎozi, zhè jiùshì qǔ “Gèngsuì jiāozi” de yìsi. “Jiāozi” jiùshì jiù de yìnián de zi shí yǔ xīn de yìnián de zi shí xiāngjiāo de shíkè. “Jiǎozi” de míngchēng jiù yóucǐ délái. Chúle chījiǎozi zhīwài hái chī niángāo, húntún, qǔ “Yìnián bǐ yìnián gāo” hé “Jiéshù xīnjiùjiāotì de hùndùn zhuàngtài” de yùyì.", "vi": "Tết Xuân là ngày cả nhà đoàn tụ. Tối hôm trước Tết gọi là “trừ tịch”, nghĩa là bỏ cũ đón mới. Đúng nửa đêm trừ tịch, tức giờ Tý, người ta ăn sủi cảo gói từ tối, lấy ý “canh tuế giao tý”. “Giao tý” là thời khắc giờ Tý năm cũ giao với giờ Tý năm mới. Tên “sủi cảo” (饺子) bắt nguồn từ đó. Ngoài sủi cảo còn ăn bánh tổ, hoành thánh, lấy ý “năm sau cao hơn năm trước” và “kết thúc trạng thái hỗn độn giao thời cũ mới”."}, {"c": "prof", "zh": "“饺子”这个名称是怎么来的？", "py": "“Jiǎozi” zhège míngchēng shì zěnme lái de?", "vi": "Tên “饺子” từ đâu mà có?"}, {"me": "Từ “canh tuế giao tý” – giờ Tý năm cũ giao năm mới.", "opts": [["来自“更岁交子”，即新旧两年的子时相交。", "Láizì “Gèngsuì jiāozi”, jí xīnjiù liǎngnián de zi shí xiāngjiāo.", "Từ “canh tuế giao tý” – giờ Tý năm cũ giao năm mới."], ["因为饺子很好吃。", "Yīnwèi jiǎozi hěn hǎochī.", "(chưa đúng với bài)"], ["因为饺子是一个人发明的。", "Yīnwèi jiǎozi shì yíge rén fāmíng de.", "(chưa đúng với bài)"]]}, {"c": "dad", "zh": "元宵节是在农历正月十五日，是中国继春节之后的第一个重要节日。古代把这一天叫“上元节”，“宵”是夜晚的意思，于是就有了“元宵节”这个名称。元宵节是农历年的第一个月圆之夜，人们有赏灯和吃元宵的习惯。民间俗语说“三十儿的火，十五的灯”“正月十五闹元宵”。因此，元宵节又叫“灯节”。", "py": "Yuánxiāojié shì zài nónglì zhēngyuèshíwǔ rì, shì zhōngguó jì chūnjié zhīhòu de dìyīge zhòngyào jiérì. Gǔdài bǎ zhè yìtiān jiào “Shàngyuánjié”, “Xiāo” shì yèwǎn de yìsi, yúshì jiù yǒu le “Yuánxiāojié” zhège míngchēng. Yuánxiāojié shì nónglìnián de dìyīge yuè yuánzhīyè, rénmen yǒushǎng dēng hé chī yuánxiāo de xíguàn. Mínjiān súyǔshuō “Sānshí ér de huǒ, shíwǔ de dēng” “Zhēngyuèshíwǔ nàoyuánxiāo”. Yīncǐ, yuánxiāojié yòu jiào “Dēngjié”.", "vi": "Tết Nguyên Tiêu vào ngày rằm tháng Giêng, là ngày lễ quan trọng đầu tiên sau Tết Xuân. Xưa gọi ngày này là “Thượng Nguyên tiết”, “tiêu” nghĩa là đêm, nên có tên “Nguyên Tiêu”. Đây là đêm trăng tròn đầu tiên của năm âm lịch, người ta có tục ngắm đèn và ăn bánh trôi. Tục ngữ có câu “lửa đêm ba mươi, đèn đêm rằm”, “rằm tháng Giêng náo nhiệt Nguyên Tiêu”. Vì thế Nguyên Tiêu còn gọi là “Tết đèn”."}, {"c": "prof", "zh": "元宵节为什么又叫“灯节”？", "py": "Yuánxiāojié wèishénme yòu jiào “Dēngjié”?", "vi": "Vì sao Nguyên Tiêu còn gọi là “Tết đèn”?"}, {"me": "Vì người ta có tục ngắm đèn.", "opts": [["因为人们有赏灯的习惯，“正月十五闹元宵”。", "Yīnwèi rénmen yǒushǎng dēng de xíguàn, “Zhēngyuèshíwǔ nàoyuánxiāo”.", "Vì người ta có tục ngắm đèn."], ["因为那天停电了。", "Yīnwèi nàtiān tíngdiàn le.", "(chưa đúng với bài)"], ["因为灯笼很便宜。", "Yīnwèi dēnglóng hěn piányi.", "(chưa đúng với bài)"]]}, {"c": "mom", "zh": "端午节，人们喜欢吃粽子。粽子的制作是用竹叶或苇叶把糯米包住，扎成三角形、四角形或其他形状，用线绳扎紧煮食。包粽子也来自中国人民对屈原的崇敬和爱戴。屈原投江以后，人们没有打捞到屈原，为了不让鱼虾损伤屈原的尸体，人们纷纷用竹筒装米扔到江里喂鱼虾，这就是最初的粽子“筒粽”的由来。后来人们用竹叶或苇叶代替竹筒，就慢慢变成今天人们吃的粽子，粽子也不再投入江中，而成为一种传统的节日食品。", "py": "Duānwǔjié, rénmen xǐhuan chī zòngzi. Zòngzi de zhìzuò shì yòng zhúyè huò wěiyè bǎ nuòmǐ bāozhù, zhāchéng sānjiǎoxíng, sìjiǎoxíng huò qítā xíngzhuàng, yòng xiànshéng zhājǐn zhǔshí. Bāo zòngzi yě láizì zhōngguó rénmín duì qūyuán de chóngjìng hé àidài. Qūyuán tóujiāng yǐhòu, rénmen méiyǒu dǎlāodào qūyuán, wèile búràng yúxiā sǔnshāng qūyuán de shītǐ, rénmen fēnfēn yòng zhútǒng zhuāngmǐ rēng dào jiānglǐ wèi yúxiā, zhè jiùshì zuìchū de zòngzi “Tǒng zòng” de yóu lái. Hòulái rénmen yòng zhúyè huò wěiyè dàitì zhútǒng, jiù mànmàn biànchéng jīntiān rénmen chī de zòngzi, zòngzi yě búzài tóurù jiāngzhōng, ér chéngwéi yìzhǒng chuántǒng de jiérì shípǐn.", "vi": "Tết Đoan Ngọ người ta thích ăn bánh ú (zòngzi). Bánh làm bằng gạo nếp gói trong lá tre hoặc lá lau, buộc thành hình tam giác, tứ giác, dùng dây buộc chặt rồi luộc. Gói bánh ú cũng bắt nguồn từ lòng kính yêu của nhân dân với Khuất Nguyên. Sau khi Khuất Nguyên trầm mình xuống sông, người ta không vớt được ông; để cá tôm không làm hại thi thể ông, mọi người đổ gạo vào ống tre ném xuống sông cho cá tôm ăn, đó là nguồn gốc của “bánh ống” – chiếc bánh ú đầu tiên. Về sau người ta dùng lá tre, lá lau thay ống tre, dần thành bánh ú ngày nay, và bánh không còn ném xuống sông mà thành món ăn truyền thống ngày lễ."}, {"c": "prof", "zh": "最初的粽子是怎么来的？", "py": "Zuìchū de zòngzi shì zěnme lái de?", "vi": "Bánh ú đầu tiên ra đời thế nào?"}, {"me": "Người ta bỏ gạo vào ống tre ném xuống sông cho cá tôm, bảo vệ thi thể Khuất Nguyên.", "opts": [["人们用竹筒装米扔到江里喂鱼虾，保护屈原的尸体。", "Rénmen yòng zhútǒng zhuāngmǐ rēng dào jiānglǐ wèi yúxiā, bǎohù qūyuán de shītǐ.", "Người ta bỏ gạo vào ống tre ném xuống sông cho cá tôm, bảo vệ thi thể Khuất Nguyên."], ["皇帝命令大家吃粽子。", "Huángdì mìnglìng dàjiā chī zòngzi.", "(chưa đúng với bài)"], ["人们在山上发现了粽子。", "Rénmen zài shānshàng fāxiàn le zòngzi.", "(chưa đúng với bài)"]]}, {"c": "meimei", "zh": "中秋节是中国的传统节日。每年农历八月十五日是一年秋季的中期，所以这一天被称为中秋节。中秋节又称“团圆节”，这一天人们仰望明月，盼望家人团聚。远在他乡的游子，也借此寄托对故乡和亲人的思念之情。中秋节自古便有祭月、赏月、吃月饼、玩花灯、赏桂花、饮桂花酒等民俗，流传至今，经久不息。", "py": "Zhōngqiūjié shì zhōngguó de chuántǒngjiérì. Měinián nónglì bāyuè shíwǔrì shì yìnián qiūjì de zhōngqī, suǒyǐ zhè yìtiān bèi chēngwéi zhōngqiūjié. Zhōngqiūjié yòuchēng “Tuányuánjié”, zhè yìtiān rénmen yǎngwàng míngyuè, pànwàng jiārén tuánjù. Yuǎnzàitāxiāng de yóuzi, yě jiècǐ jìtuō duì gùxiāng hé qīnrén de sīniàn zhīqíng. Zhōngqiūjié zìgǔ biàn yǒu jì yuè, shǎngyuè, chī yuèbǐng, wán huādēng, shǎng guìhuā, yǐn guìhuājiǔ děng mínsú, liúchuán zhìjīn, jīngjiǔbùxī.", "vi": "Tết Trung Thu là ngày lễ truyền thống của Trung Quốc. Rằm tháng Tám âm lịch là giữa mùa thu, nên ngày này gọi là Trung Thu. Trung Thu còn gọi là “Tết đoàn viên”, hôm ấy người ta ngắm trăng sáng, mong người nhà sum họp. Người con xa quê cũng nhân đó gửi gắm nỗi nhớ quê hương, người thân. Từ xưa Trung Thu đã có tục cúng trăng, ngắm trăng, ăn bánh trung thu, chơi đèn, ngắm hoa quế, uống rượu hoa quế…, lưu truyền đến nay không dứt."}, {"c": "prof", "zh": "中秋节为什么又叫“团圆节”？", "py": "Zhōngqiūjié wèishénme yòu jiào “Tuányuánjié”?", "vi": "Vì sao Trung Thu còn gọi là “Tết đoàn viên”?"}, {"me": "Người ta ngắm trăng, mong gia đình sum họp.", "opts": [["人们仰望明月，盼望家人团聚。", "Rénmen yǎngwàng míngyuè, pànwàng jiārén tuánjù.", "Người ta ngắm trăng, mong gia đình sum họp."], ["因为月饼是圆的，很好吃。", "Yīnwèi yuèbǐng shì yuán de, hěn hǎochī.", "(chưa đúng với bài)"], ["因为那天要去旅游。", "Yīnwèi nàtiān yào qù lǚyóu.", "(chưa đúng với bài)"]]}, {"c": "dad", "zh": "今天的重阳节，被赋予了新的含义。1989年，中国把每年的九月九日定为老人节，增加了重阳节敬老的内涵。传统与现代巧妙地结合，成为尊老、敬老、爱老、助老的老年人的节日。今日登高赏秋与感恩敬老是当今重阳节活动的两大重要主题。", "py": "Jīntiān de chóngyángjié, bèi fùyǔ le xīn de hányì. 1989 nián, zhōngguó bǎ měinián de jiǔyuèjiǔ rì dìngwèi lǎorénjié, zēngjiā le chóngyángjié jìnglǎo de nèihán. Chuántǒng yǔ xiàndài qiǎomiào dì jiéhé, chéngwéi zūnlǎo, jìnglǎo, àilǎo, zhùlǎo de lǎoniánrén de jiérì. Jīnrì dēnggāo shǎngqiū yǔ gǎnēn jìnglǎo shì dāngjīn chóngyángjié huódòng de liǎngdà zhòngyào zhǔtí.", "vi": "Tết Trùng Dương ngày nay được trao thêm ý nghĩa mới. Năm 1989, Trung Quốc lấy ngày mùng 9 tháng 9 hằng năm làm Ngày Người cao tuổi, thêm nội hàm kính lão cho Tết Trùng Dương. Truyền thống và hiện đại kết hợp khéo léo, thành ngày lễ của người già với tinh thần tôn lão, kính lão, yêu lão, giúp lão. Lên cao ngắm thu và tri ân kính lão là hai chủ đề quan trọng của Tết Trùng Dương ngày nay."}, {"c": "prof", "zh": "1989年以后，重阳节增加了什么内涵？", "py": "1989 nián yǐhòu, chóngyángjié zēngjiā le shénme nèihán?", "vi": "Từ 1989, Trùng Dương thêm ý nghĩa gì?"}, {"me": "Ý nghĩa kính lão, mùng 9/9 thành Ngày Người cao tuổi.", "opts": [["敬老的内涵，九月九日成了老人节。", "Jìnglǎo de nèihán, jiǔyuèjiǔ rìchéng le lǎorénjié.", "Ý nghĩa kính lão, mùng 9/9 thành Ngày Người cao tuổi."], ["成了儿童节。", "Chéng le értóngjié.", "(chưa đúng với bài)"], ["成了教师节。", "Chéng le jiàoshījié.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "把……叫(做)……", "d": "Gọi… là….", "ex": [["中国人把过春节叫“过年”。", "Zhōngguó rén bǎ guò chūnjié jiào “Guònián”.", "Người Trung Quốc gọi ăn Tết là “qua năm”."]]}, {"t": "除了……之外还……", "d": "Ngoài… ra còn….", "ex": [["除了吃饺子之外，还吃年糕、馄饨。", "Chúle chījiǎozi zhīwài, hái chī niángāo, húntún.", "Ngoài sủi cảo còn ăn bánh tổ, hoành thánh."]]}, {"t": "取……之意 / 取……的意思", "d": "Lấy ý….", "ex": [["这些名称与“团圆”相近，取团圆之意。", "Zhèxiē míngchēng yǔ “Tuányuán” xiāngjìn, qǔ tuányuán zhīyì.", "Những tên này gần với “đoàn viên”, lấy ý đoàn viên."]]}, {"t": "为了不让……", "d": "Để không cho….", "ex": [["为了不让鱼虾损伤屈原的尸体，人们把米扔到江里。", "Wèile búràng yúxiā sǔnshāng qūyuán de shītǐ, rénmen bǎ mǐ rēng dào jiānglǐ.", "Để cá tôm không làm hại thi thể Khuất Nguyên, người ta ném gạo xuống sông."]]}, {"t": "无论……都……", "d": "Bất luận… đều….", "ex": [["无论身在何地，心中都有一个共同的愿望。", "Wúlùn shēnzài hédì, xīnzhōng dōu yǒu yíge gòngtóng de yuànwàng.", "Dù ở đâu, trong lòng đều có chung một mong ước."]]}], "order": [], "u": {"gq": [{"s": "把……叫(做)……", "d": "Gọi… là….", "ok": "中国人把过春节叫“过年”。", "vi": "Người Trung Quốc gọi ăn Tết là “qua năm”.", "bad": ["中国人把“过年”叫过春节了把。", "中国人叫把过春节“过年”。"]}, {"s": "除了……之外还……", "d": "Ngoài… ra còn….", "ok": "除了吃饺子之外，还吃年糕、馄饨。", "vi": "Ngoài sủi cảo còn ăn bánh tổ, hoành thánh.", "bad": ["除了吃饺子之外，就吃年糕、馄饨。", "除了之外吃饺子，还吃年糕、馄饨。"]}, {"s": "取……之意 / 取……的意思", "d": "Lấy ý….", "ok": "这些名称与“团圆”相近，取团圆之意。", "vi": "Những tên này gần với “đoàn viên”, lấy ý đoàn viên.", "bad": ["这些名称与“团圆”相近，之意取团圆。", "这些名称与“团圆”相近，取之团圆意。"]}, {"s": "为了不让……", "d": "Để không cho….", "ok": "为了不让鱼虾损伤屈原的尸体，人们把米扔到江里。", "vi": "Để cá tôm không làm hại thi thể Khuất Nguyên, người ta ném gạo xuống sông.", "bad": ["为了让不鱼虾损伤屈原的尸体，人们把米扔到江里。", "不为了让鱼虾损伤屈原的尸体，人们把米扔到江里。"]}, {"s": "无论……都……", "d": "Bất luận… đều….", "ok": "无论身在何地，心中都有一个共同的愿望。", "vi": "Dù ở đâu, trong lòng đều có chung một mong ước.", "bad": ["无论身在何地，心中就有一个共同的愿望。", "虽然身在何地，心中都有一个共同的愿望。"]}], "disc": [{"q": "越南的春节、中秋节和中国的有什么相同和不同？", "py": "Yuènán de chūnjié, zhōngqiūjié hé zhōngguó de yǒu shénme xiāngtóng hé bùtóng?", "vi": "Tết, Trung Thu ở Việt Nam và Trung Quốc giống và khác nhau thế nào?", "keys": ["除了……之外|除了……以外", "无论……都", "把……叫|把……当作"], "sample": "越南也过春节和中秋节。中国人除夕吃饺子，越南人除了吃粽子之外，还吃春卷。越南把中秋节叫做儿童节，无论大人还是孩子都喜欢提灯笼。", "spy": "Yuènán yě guò chūnjié hé zhōngqiūjié. Zhōngguó rén chúxī chījiǎozi, yuènánrén chúle chī zòngzi zhīwài, hái chī chūnjuǎn. Yuènán bǎ zhōngqiūjié jiàozuò értóngjié, wúlùn dàrén háishì háizi dōu xǐhuan tí dēnglóng."}], "comp": [{"vi": "Người Việt gọi Tết Trung Thu là Tết thiếu nhi. (把……叫……)", "keys": ["把", "叫"], "model": "越南人把中秋节叫儿童节。", "mpy": "Yuènánrén bǎ zhōngqiūjié jiào értóngjié."}, {"vi": "Bất luận bận thế nào, Tết tôi đều về nhà. (无论……都……)", "keys": ["无论", "都"], "model": "无论多忙，春节我都回家。", "mpy": "Wúlùn duōmáng, chūnjié wǒ dōu huíjiā."}, {"vi": "Ngoài bánh trung thu ra, chúng tôi còn ăn bưởi. (除了……之外还……)", "keys": ["除了", "还"], "model": "除了月饼之外，我们还吃柚子。", "mpy": "Chúle yuèbǐng zhīwài, wǒmen hái chī yòuzi."}], "ex": [{"q": "中国人把过春节叫什么？", "qvi": "Người Trung Quốc gọi ăn Tết là gì?", "a": "叫“过年”。", "avi": "Gọi là “qua năm”.", "bad": ["叫“过节日”。", "叫“元宵”。"], "p": 0}, {"q": "“饺子”这个名称是怎么来的？", "qvi": "Tên “饺子” từ đâu mà có?", "a": "来自“更岁交子”，即新旧两年的子时相交。", "avi": "Từ “canh tuế giao tý” – giờ Tý năm cũ giao năm mới.", "bad": ["因为饺子很好吃。", "因为饺子是一个人发明的。"], "p": 1}, {"q": "元宵节为什么又叫“灯节”？", "qvi": "Vì sao Nguyên Tiêu còn gọi là “Tết đèn”?", "a": "因为人们有赏灯的习惯，“正月十五闹元宵”。", "avi": "Vì người ta có tục ngắm đèn.", "bad": ["因为那天停电了。", "因为灯笼很便宜。"], "p": 2}, {"q": "最初的粽子是怎么来的？", "qvi": "Bánh ú đầu tiên ra đời thế nào?", "a": "人们用竹筒装米扔到江里喂鱼虾，保护屈原的尸体。", "avi": "Người ta bỏ gạo vào ống tre ném xuống sông cho cá tôm, bảo vệ thi thể Khuất Nguyên.", "bad": ["皇帝命令大家吃粽子。", "人们在山上发现了粽子。"], "p": 3}, {"q": "中秋节为什么又叫“团圆节”？", "qvi": "Vì sao Trung Thu còn gọi là “Tết đoàn viên”?", "a": "人们仰望明月，盼望家人团聚。", "avi": "Người ta ngắm trăng, mong gia đình sum họp.", "bad": ["因为月饼是圆的，很好吃。", "因为那天要去旅游。"], "p": 4}, {"q": "1989年以后，重阳节增加了什么内涵？", "qvi": "Từ 1989, Trùng Dương thêm ý nghĩa gì?", "a": "敬老的内涵，九月九日成了老人节。", "avi": "Ý nghĩa kính lão, mùng 9/9 thành Ngày Người cao tuổi.", "bad": ["成了儿童节。", "成了教师节。"], "p": 5}]}}, {"id": "hk4-l15", "no": 15, "day": "HK4 · Đất nước học 4", "time": "20:00", "scene": "library", "room": "library", "cast": ["prof", "edward", "zhangdong", "roland"], "vi": "Thơ Đường và tiểu thuyết Minh Thanh", "zh": "唐诗与明清小说", "py": "Tángshī yǔ míngqīngxiǎoshuō", "shop": {"label": "诗社", "sub": "Thi xã", "icon": "🖋️"}, "vocab": [["高峰", "Gāofēng", "đỉnh cao", ""], ["空前", "Kōngqián", "chưa từng có", ""], ["繁荣", "Fánróng", "phồn vinh", ""], ["抒情", "Shūqíng", "trữ tình", ""], ["题材", "Tícái", "đề tài", ""], ["百花齐放", "Bǎihuāqífàng", "trăm hoa đua nở", ""], ["律诗", "Lǜshī", "luật thi", ""], ["绝句", "Juéjù", "tuyệt cú", ""], ["精练", "Jīngliàn", "tinh luyện", ""], ["喜闻乐见", "Xǐwénlèjiàn", "ưa thích", ""], ["游览", "Yóulǎn", "du ngoạn", ""], ["豪迈奔放", "Háomài bēnfàng", "hào phóng phóng khoáng", ""], ["浪漫主义", "Làngmànzhǔyì", "chủ nghĩa lãng mạn", ""], ["诗仙", "Shīxiān", "thi tiên", ""], ["诗史", "Shīshǐ", "thi sử", ""], ["诗圣", "Shīshèng", "thi thánh", ""], ["兴盛", "Xīngshèng", "hưng thịnh", ""], ["名著", "Míngzhù", "danh tác", ""], ["杰出", "Jiéchū", "kiệt xuất", ""], ["取经", "Qǔjīng", "thỉnh kinh", ""], ["幽默", "Yōumò", "hài hước", ""], ["意味深长", "Yìwèishēncháng", "ý vị sâu xa", ""], ["神通广大", "Shéntōngguǎngdà", "thần thông quảng đại", ""], ["反抗", "Fǎnkàng", "phản kháng", ""]], "story": [{"c": "panda", "vi": "Đất nước học · Thơ Đường và tiểu thuyết Minh Thanh. Đọc đoạn giáo trình gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "edward", "zh": "中国文学在唐代进入了一个高峰时期，诗歌发展达到了空前繁荣的阶段。中国是诗的国度，自古以来，中国人就有用诗歌抒情的传统。唐代诗歌数量极大，题材广泛，形式和风格丰富多彩，出现了大量思想性和艺术性完美结合的作品，真正是一个百花齐放的黄金时代。唐代不仅有前代句式自由的诗歌，而且还创造了句式固定整齐的新体诗，这就是律诗和绝句。这种新体诗把中国古代诗歌音节和谐、文字精练的艺术特色推到一个新的高度，成为古代抒情诗的典型形式，至今还特别为人民所喜闻乐见。", "py": "Zhōngguó wénxué zài tángdài jìnrù le yíge gāofēng shíqī, shīgē fāzhǎn dádào le kōngqián fánróng de jiēduàn. Zhōngguó shì shī de guódù, zìgǔyǐlái, zhōngguó rén jiù yǒuyòng shīgē shūqíng de chuántǒng. Tángdài shīgē shùliàng jídà, tícái guǎngfàn, xíngshì hé fēnggé fēngfùduōcǎi, chūxiàn le dàliàng sīxiǎngxìng hé yìshùxìng wánměi jiéhé de zuòpǐn, zhēnzhèng shì yíge bǎihuāqífàng de huángjīnshídài. Tángdài bùjǐn yǒu qiándài jùshì zìyóu de shīgē, érqiě hái chuàngzào le jùshì gùdìng zhěngqí de xīntǐshī, zhè jiùshì lǜshī hé juéjù. Zhèzhǒng xīntǐshī bǎ zhōngguó gǔdài shīgē yīnjié héxié, wénzì jīngliàn de yìshù tèsè tuī dào yíge xīn de gāodù, chéngwéi gǔdài shūqíngshī de diǎnxíng xíngshì, zhìjīn hái tèbié wèi rénmín suǒ xǐwénlèjiàn.", "vi": "Văn học Trung Quốc thời Đường bước vào thời kỳ đỉnh cao, thơ ca phát triển đến giai đoạn phồn thịnh chưa từng có. Trung Quốc là đất nước của thơ, từ xưa người Trung Quốc đã có truyền thống dùng thơ để bày tỏ tình cảm. Thơ Đường số lượng rất lớn, đề tài rộng, hình thức và phong cách phong phú, xuất hiện nhiều tác phẩm kết hợp hoàn mỹ tư tưởng và nghệ thuật, thật sự là thời kỳ hoàng kim trăm hoa đua nở. Đời Đường không chỉ có thơ câu tự do của các đời trước mà còn sáng tạo thể thơ mới có câu cố định, chỉnh tề, đó là luật thi và tuyệt cú. Thể thơ mới này đưa đặc sắc nghệ thuật hài hòa âm tiết, tinh luyện ngôn từ lên tầm cao mới, thành hình thức tiêu biểu của thơ trữ tình cổ, đến nay vẫn được nhân dân ưa thích."}, {"c": "prof", "zh": "唐代创造了什么新体诗？", "py": "Tángdài chuàngzào le shénme xīntǐshī?", "vi": "Đời Đường sáng tạo thể thơ mới nào?"}, {"me": "Luật thi và tuyệt cú.", "opts": [["律诗和绝句。", "Lǜshī hé juéjù.", "Luật thi và tuyệt cú."], ["散文和小说。", "Sǎnwén hé xiǎoshuō.", "(chưa đúng với bài)"], ["自由诗和儿歌。", "Zìyóushī hé érgē.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "李白（字太白，公元701年—762年），他一生大部分时间生活在唐朝最强盛的时期。李白喜欢游览名山大川，写了大量赞美祖国山河的诗篇，他在《望庐山瀑布》诗中写了庐山瀑布飞泻的壮丽景象。李白的诗气既豪迈奔放，又清新飘逸，而且想象丰富，语言轻快，天真素朴，具有浪漫主义色彩。他一生写了一千多首诗，代表作有《静夜思》、《行路难》、《梦游天姥吟留别》、《蜀道难》、《望庐山瀑布》等，被奉为“诗仙”。", "py": "Lǐbái (Zì tàibái, gōngyuán701 nián—762 nián), tā yìshēng dàbùfèn shíjiān shēnghuó zài tángcháo zuì qiángshèng de shíqī. Lǐbái xǐhuan yóulǎn míngshāndàchuān, xiě le dàliàng zànměi zǔguó shānhé de shīpiān, tā zài «Wàng lúshān pùbù» shīzhōng xiě le lúshān pùbù fēixiè de zhuànglì jǐngxiàng. Lǐbái de shīqì jì háomài bēnfàng, yòu qīngxīn piāoyì, érqiě xiǎngxiàng fēngfù, yǔyán qīngkuài, tiānzhēn sùpiáo, jùyǒu làngmànzhǔyì sècǎi. Tā yìshēng xiě le yìqiānduō shǒushī, dàibiǎozuò yǒu «Jìngyè sī», «Xínglùnán», «Mèngyóu tiānlǎoyín liúbié», «Shǔdàonán», «Wàng lúshān pùbù» děng, bèi fèng wèi “Shīxiān”.", "vi": "Lý Bạch (tự Thái Bạch, 701–762), phần lớn cuộc đời sống vào thời Đường thịnh vượng nhất. Ông thích du ngoạn danh sơn đại xuyên, viết nhiều bài ca ngợi núi sông đất nước; trong bài 《Vọng Lư Sơn bộc bố》 ông tả cảnh thác Lư Sơn đổ xuống hùng vĩ. Thơ Lý Bạch vừa hào phóng phóng khoáng, vừa thanh tân phiêu dật, giàu tưởng tượng, ngôn ngữ nhẹ nhàng, hồn nhiên mộc mạc, mang màu sắc lãng mạn. Cả đời ông viết hơn nghìn bài, tiêu biểu có 《Tĩnh dạ tư》, 《Hành lộ nan》, 《Thục đạo nan》…, được tôn là “Thi tiên”."}, {"c": "prof", "zh": "李白的诗有什么特点？", "py": "Lǐbái de shī yǒu shénme tèdiǎn?", "vi": "Thơ Lý Bạch có đặc điểm gì?"}, {"me": "Hào phóng, thanh tân, giàu tưởng tượng, màu sắc lãng mạn.", "opts": [["豪迈奔放，清新飘逸，想象丰富，有浪漫主义色彩。", "Háomài bēnfàng, qīngxīn piāoyì, xiǎngxiàng fēngfù, yǒu làngmànzhǔyì sècǎi.", "Hào phóng, thanh tân, giàu tưởng tượng, màu sắc lãng mạn."], ["只写社会的黑暗。", "Zhǐ xiě shèhuì de hēiàn.", "(chưa đúng với bài)"], ["语言很难懂。", "Yǔyán hěn nándǒng.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "杜甫一生写了1400多首诗，他的诗语言精练，感情深沉。因为杜甫的诗反映了当时的历史面貌，所以后人称他的诗为“诗史”。人们热爱杜甫，也称他为“诗圣”。", "py": "Dùfǔ yìshēng xiě le1400 duōshǒu shī, tā de shī yǔyán jīngliàn, gǎnqíng shēnchén. Yīnwèi dùfǔ de shī fǎnyìng le dāngshí de lìshǐ miànmào, suǒyǐ hòu rénchēng tā de shī wèi “Shīshǐ”. Rénmen rèài dùfǔ, yě chēng tā wèi “Shīshèng”.", "vi": "Đỗ Phủ cả đời viết hơn 1400 bài thơ, ngôn ngữ tinh luyện, tình cảm sâu lắng. Vì thơ Đỗ Phủ phản ánh diện mạo lịch sử đương thời nên người sau gọi thơ ông là “thi sử”. Người ta yêu quý Đỗ Phủ và cũng gọi ông là “Thi thánh”."}, {"c": "prof", "zh": "后人为什么称杜甫的诗为“诗史”？", "py": "Hòurén wèishénme chēng dùfǔ de shī wèi “Shīshǐ”?", "vi": "Vì sao thơ Đỗ Phủ được gọi là “thi sử”?"}, {"me": "Vì thơ ông phản ánh diện mạo lịch sử đương thời.", "opts": [["因为他的诗反映了当时的历史面貌。", "Yīnwèi tā de shī fǎnyìng le dāngshí de lìshǐ miànmào.", "Vì thơ ông phản ánh diện mạo lịch sử đương thời."], ["因为他是历史老师。", "Yīnwèi tā shì lìshǐ lǎoshī.", "(chưa đúng với bài)"], ["因为他只写了历史书。", "Yīnwèi tā zhǐ xiě le lìshǐ shū.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "明清两代是中国古典小说兴盛繁荣的时代，出现了一批优秀的长篇章回小说，还有一大批优秀的短篇小说集。四大文学名著《三国演义》、《水浒传》、《西游记》、《红楼梦》是这一时期的杰出成就。", "py": "Míngqīngliǎngdài shì zhōngguó gǔdiǎnxiǎoshuō xīngshèng fánróng de shídài, chūxiàn le yìpī yōuxiù de chángpiān zhānghuíxiǎoshuō, háiyǒu yídàpī yōuxiù de duǎnpiānxiǎoshuō jí. Sìdà wénxuémíngzhù «Sānguóyǎnyì», «Shuǐhǔzhuàn», «Xīyóujì», «Hónglóumèng» shì zhè yìshíqī de jiéchūchéngjiù.", "vi": "Hai đời Minh Thanh là thời kỳ tiểu thuyết cổ điển Trung Quốc hưng thịnh, xuất hiện một loạt tiểu thuyết chương hồi dài xuất sắc và nhiều tập truyện ngắn ưu tú. Bốn danh tác 《Tam quốc diễn nghĩa》, 《Thủy hử》, 《Tây du ký》, 《Hồng lâu mộng》 là thành tựu kiệt xuất của thời kỳ này."}, {"c": "prof", "zh": "中国四大文学名著是哪四部？", "py": "Zhōngguó sìdà wénxuémíngzhù shì nǎ sìbù?", "vi": "Bốn danh tác văn học Trung Quốc là những bộ nào?"}, {"me": "Tam quốc, Thủy hử, Tây du ký, Hồng lâu mộng.", "opts": [["《三国演义》《水浒传》《西游记》《红楼梦》。", "«Sānguóyǎnyì» «Shuǐhǔzhuàn» «Xīyóujì» «Hónglóumèng».", "Tam quốc, Thủy hử, Tây du ký, Hồng lâu mộng."], ["《诗经》《论语》《春秋》《史记》。", "«Shījīng» «Lúnyǔ» «Chūnqiū» «Shǐjì».", "(chưa đúng với bài)"], ["《静夜思》《春望》《兵车行》《蜀道难》。", "«Jìngyè sī» «Chūnwàng» «Bīngchēxíng» «Shǔdàonán».", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "《西游记》的作者为吴承恩，他在民间流行的唐僧西天取经的故事的基础上创造而成，共有100回。小说记述了唐僧师徒西天取经，经过九九八十一难的曲折历程，最后取回了佛经。《西游记》小说充满了神奇色彩，它最大的特点就是幽默和诙谐，语言轻松活泼，既引人发笑，又意味深长。作品塑造了孙悟空、猪八戒等性格鲜明的人物，其中神通广大、会72种变化的孙悟空是最受人们喜爱的。他的形象实际上反映了人民反抗封建统治、勇于斗争的精神。", "py": "«Xīyóujì» de zuòzhě wèi wúchéngēn, tā zài mínjiān liúxíng de tángsēng xītiān qǔjīng de gùshi de jīchǔ shàng chuàngzào érchéng, gòngyǒu100 huí. Xiǎoshuō jìshù le tángsēng shītú xītiān qǔjīng, jīngguò jiǔ jiǔ bā shí yī nán de qūzhé lìchéng, zuìhòu qǔhuí le fójīng. «Xīyóujì» xiǎoshuō chōngmǎn le shénqí sècǎi, tā zuìdà de tèdiǎn jiùshì yōumò hé huīxié, yǔyán qīngsōng huópō, jì yǐnrén fāxiào, yòu yìwèishēncháng. Zuòpǐn sùzào le sūnwùkōng, zhūbājiè děng xìnggé xiānmíng de rénwù, qízhōng shéntōngguǎngdà, huì72 zhǒng biànhuà de sūnwùkōng shì zuìshòu rénmen xǐài de. Tā de xíngxiàng shíjìshàng fǎnyìng le rénmín fǎnkàng fēngjiàntǒngzhì, yǒngyú dòuzhēng de jīngshén.", "vi": "《Tây du ký》 của Ngô Thừa Ân được sáng tác dựa trên truyện dân gian Đường Tăng sang Tây Thiên thỉnh kinh, gồm 100 hồi. Truyện kể thầy trò Đường Tăng đi thỉnh kinh, trải qua chín chín tám mươi mốt kiếp nạn, cuối cùng thỉnh được kinh Phật. Tiểu thuyết đầy màu sắc thần kỳ, đặc điểm lớn nhất là hài hước dí dỏm, ngôn ngữ nhẹ nhàng sinh động, vừa gây cười vừa sâu sắc. Tác phẩm xây dựng các nhân vật cá tính rõ nét như Tôn Ngộ Không, Trư Bát Giới; trong đó Tôn Ngộ Không thần thông quảng đại, biết 72 phép biến hóa được yêu thích nhất. Hình tượng ông thực ra phản ánh tinh thần phản kháng ách thống trị phong kiến, dám đấu tranh của nhân dân."}, {"c": "prof", "zh": "孙悟空的形象反映了什么？", "py": "Sūnwùkōng de xíngxiàng fǎnyìng le shénme?", "vi": "Hình tượng Tôn Ngộ Không phản ánh điều gì?"}, {"me": "Tinh thần phản kháng phong kiến, dám đấu tranh của nhân dân.", "opts": [["人民反抗封建统治、勇于斗争的精神。", "Rénmín fǎnkàng fēngjiàntǒngzhì, yǒngyú dòuzhēng de jīngshén.", "Tinh thần phản kháng phong kiến, dám đấu tranh của nhân dân."], ["人们喜欢猴子。", "Rénmen xǐhuan hóuzi.", "(chưa đúng với bài)"], ["唐僧很厉害。", "Tángsēng hěn lìhài.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "不仅……而且还……", "d": "Không chỉ… mà còn….", "ex": [["唐代不仅有句式自由的诗歌，而且还创造了新体诗。", "Tángdài bùjǐn yǒu jùshì zìyóu de shīgē, érqiě hái chuàngzào le xīntǐshī.", "Đời Đường không chỉ có thơ tự do mà còn sáng tạo thể thơ mới."]]}, {"t": "为……所……", "d": "Được… (bị động văn viết).", "ex": [["新体诗至今还特别为人民所喜闻乐见。", "Xīntǐshī zhìjīn hái tèbié wèi rénmín suǒ xǐwénlèjiàn.", "Thể thơ mới đến nay vẫn được nhân dân ưa thích."]]}, {"t": "被奉为……", "d": "Được tôn là….", "ex": [["李白被奉为“诗仙”。", "Lǐbái bèi fèng wèi “Shīxiān”.", "Lý Bạch được tôn là “Thi tiên”."]]}, {"t": "因为……所以……", "d": "Vì… nên….", "ex": [["因为杜甫的诗反映了当时的历史面貌，所以后人称他的诗为“诗史”。", "Yīnwèi dùfǔ de shī fǎnyìng le dāngshí de lìshǐ miànmào, suǒyǐ hòu rénchēng tā de shī wèi “Shīshǐ”.", "Vì thơ Đỗ Phủ phản ánh lịch sử đương thời nên người sau gọi là thi sử."]]}, {"t": "既……又……", "d": "Vừa… vừa….", "ex": [["《西游记》的语言既引人发笑，又意味深长。", "«Xīyóujì» de yǔyán jì yǐnrén fāxiào, yòu yìwèishēncháng.", "Ngôn ngữ Tây du ký vừa gây cười vừa sâu sắc."]]}], "order": [], "u": {"gq": [{"s": "不仅……而且还……", "d": "Không chỉ… mà còn….", "ok": "唐代不仅有句式自由的诗歌，而且还创造了新体诗。", "vi": "Đời Đường không chỉ có thơ tự do mà còn sáng tạo thể thơ mới.", "bad": ["唐代不仅有句式自由的诗歌，所以还创造了新体诗。", "不仅唐代有句式自由的诗歌，还而且创造了新体诗。"]}, {"s": "为……所……", "d": "Được… (bị động văn viết).", "ok": "新体诗至今还特别为人民所喜闻乐见。", "vi": "Thể thơ mới đến nay vẫn được nhân dân ưa thích.", "bad": ["新体诗至今还特别所人民为喜闻乐见。", "新体诗至今还特别为人民喜闻乐见所。"]}, {"s": "被奉为……", "d": "Được tôn là….", "ok": "李白被奉为“诗仙”。", "vi": "Lý Bạch được tôn là “Thi tiên”.", "bad": ["李白奉为被“诗仙”。", "李白被“诗仙”奉为。"]}, {"s": "因为……所以……", "d": "Vì… nên….", "ok": "因为杜甫的诗反映了当时的历史面貌，所以后人称他的诗为“诗史”。", "vi": "Vì thơ Đỗ Phủ phản ánh lịch sử đương thời nên người sau gọi là thi sử.", "bad": ["因为杜甫的诗反映了当时的历史面貌，但是后人称他的诗为“诗史”。", "所以杜甫的诗反映了当时的历史面貌，因为后人称他的诗为“诗史”。"]}, {"s": "既……又……", "d": "Vừa… vừa….", "ok": "《西游记》的语言既引人发笑，又意味深长。", "vi": "Ngôn ngữ Tây du ký vừa gây cười vừa sâu sắc.", "bad": ["《西游记》的语言既引人发笑，也又意味深长。", "《西游记》的语言又引人发笑，既意味深长。"]}], "disc": [{"q": "你最喜欢哪部中国名著或哪位诗人？为什么？", "py": "Nǐ zuì xǐhuan nǎbù zhōngguó míngzhù huò nǎwèi shīrén? Wèishénme?", "vi": "Bạn thích nhất danh tác hay nhà thơ Trung Quốc nào? Vì sao?", "keys": ["既……又", "因为……所以|因为", "被……称为|被奉为|被称为"], "sample": "我最喜欢《西游记》，因为它既有趣又意味深长。孙悟空神通广大，所以小时候我每天都看这部电视剧。李白被奉为诗仙，我也很喜欢他的《静夜思》。", "spy": "Wǒ zuì xǐhuan «Xīyóujì», yīnwèi tā jì yǒuqù yòu yìwèishēncháng. Sūnwùkōng shéntōngguǎngdà, suǒyǐ xiǎoshíhòu wǒ měitiān dōu kàn zhèbù diànshìjù. Lǐbái bèi fèng wèi shīxiān, wǒ yě hěn xǐhuan tā de «Jìngyè sī»."}], "comp": [{"vi": "Ông ấy được gọi là “Thi thánh”. (被……称为……)", "keys": ["被", "称为|称作"], "model": "他被人们称为“诗圣”。", "mpy": "Tā bèi rénmen chēngwéi “Shīshèng”."}, {"vi": "Bài thơ này vừa ngắn vừa dễ nhớ. (既……又……)", "keys": ["既", "又"], "model": "这首诗既短又好记。", "mpy": "Zhèshǒu shī jì duǎn yòu hǎo jì."}, {"vi": "Cuốn sách này được nhiều người trẻ yêu thích. (为……所……)", "keys": ["为", "所"], "model": "这本书为很多年轻人所喜爱。", "mpy": "Zhè běnshū wèi hěnduō niánqīngrén suǒ xǐài."}], "ex": [{"q": "唐代创造了什么新体诗？", "qvi": "Đời Đường sáng tạo thể thơ mới nào?", "a": "律诗和绝句。", "avi": "Luật thi và tuyệt cú.", "bad": ["散文和小说。", "自由诗和儿歌。"], "p": 0}, {"q": "李白的诗有什么特点？", "qvi": "Thơ Lý Bạch có đặc điểm gì?", "a": "豪迈奔放，清新飘逸，想象丰富，有浪漫主义色彩。", "avi": "Hào phóng, thanh tân, giàu tưởng tượng, màu sắc lãng mạn.", "bad": ["只写社会的黑暗。", "语言很难懂。"], "p": 1}, {"q": "后人为什么称杜甫的诗为“诗史”？", "qvi": "Vì sao thơ Đỗ Phủ được gọi là “thi sử”?", "a": "因为他的诗反映了当时的历史面貌。", "avi": "Vì thơ ông phản ánh diện mạo lịch sử đương thời.", "bad": ["因为他是历史老师。", "因为他只写了历史书。"], "p": 2}, {"q": "中国四大文学名著是哪四部？", "qvi": "Bốn danh tác văn học Trung Quốc là những bộ nào?", "a": "《三国演义》《水浒传》《西游记》《红楼梦》。", "avi": "Tam quốc, Thủy hử, Tây du ký, Hồng lâu mộng.", "bad": ["《诗经》《论语》《春秋》《史记》。", "《静夜思》《春望》《兵车行》《蜀道难》。"], "p": 3}, {"q": "孙悟空的形象反映了什么？", "qvi": "Hình tượng Tôn Ngộ Không phản ánh điều gì?", "a": "人民反抗封建统治、勇于斗争的精神。", "avi": "Tinh thần phản kháng phong kiến, dám đấu tranh của nhân dân.", "bad": ["人们喜欢猴子。", "唐僧很厉害。"], "p": 4}]}}]);
  Object.assign(C.book.lessons, {"hk4-l12": {"page": "—", "src": "中国国情 · Đất nước học Trung Quốc · Bài 4  中国教育", "kw": [{"h": "课文 中国古代教育", "lines": [["", "教育在一个国家中占有重要地位，它关系到人才的培养和国民素质的提高，关系到科学、文化及整个社会的发展，所以，各个国家各个时代的政府，一般都重视教育。中国的教育历史悠久，内容丰富，不但从教育学的角度上值得研究，而且也是认识中国所需要了解的一个方面。", "Jiàoyù zài yíge guójiā zhōng zhànyǒu zhòngyào dìwèi, tā guānxi dào réncái de péiyǎng hé guómínsùzhì de tígāo, guānxi dào kēxué, wénhuà jí zhěngge shèhuì de fāzhǎn, suǒyǐ, gège guójiā gège shídài de zhèngfǔ, yìbān dōu zhòngshì jiàoyù. Zhōngguó de jiàoyù lìshǐyōujiǔ, nèiróngfēngfù, búdàn cóng jiàoyùxué de jiǎodù shàng zhíde yánjiū, érqiě yě shì rènshi zhōngguó suǒ xūyào liǎojiě de yíge fāngmiàn.", "Giáo dục giữ vị trí quan trọng trong một quốc gia, nó liên quan đến việc bồi dưỡng nhân tài và nâng cao tố chất người dân, liên quan đến sự phát triển của khoa học, văn hóa và cả xã hội, vì vậy chính phủ các nước ở mọi thời đại nói chung đều coi trọng giáo dục. Giáo dục Trung Quốc có lịch sử lâu đời, nội dung phong phú, không những đáng nghiên cứu từ góc độ giáo dục học mà còn là một mặt cần tìm hiểu để hiểu Trung Quốc."], ["", "官学建立于西周时期，是指政府开办和管理的学校，分作“国学”、“乡学”两种。“国学”设在周王朝和各诸侯国的国都，是中央设立的学校，有“大学”和“小学”之分。小学设在王宫南边左侧，大学则设在国都的南郊。“乡学”设在地方。", "Guānxué jiànlì yú xīzhōushíqī, shì zhǐ zhèngfǔ kāibàn hé guǎnlǐ de xuéxiào, fēn zuò “Guóxué”, “Xiāngxué” liǎngzhǒng. “Guóxué” shèzài zhōu wángcháo hé gè zhūhóuguó de guó dōu, shì zhōngyāng shèlì de xuéxiào, yǒu “Dàxué” hé “Xiǎoxué” zhīfēn. Xiǎoxué shèzài wánggōng nánbian zuǒcè, dàxué zé shèzài guódū de nánjiāo. “Xiāngxué” shèzài dìfāng.", "Quan học được lập từ thời Tây Chu, là trường học do nhà nước mở và quản lý, chia làm hai loại “quốc học” và “hương học”. “Quốc học” đặt ở kinh đô của nhà Chu và các nước chư hầu, là trường do trung ương lập, chia ra “đại học” và “tiểu học”. Tiểu học đặt bên trái phía nam vương cung, đại học đặt ở ngoại ô phía nam kinh đô. “Hương học” đặt ở địa phương."], ["", "秦代以后，几乎各个朝代都设立了中央官学和地方官学，有专门担任教师的官吏，以儒家著作作为基本教材。不过，由于从隋代以后中国实行了科举制度，即通过考试选拔官吏，所以，后来的官学完全服从于科举制度，成了当官的阶梯。科举制度在体现社会公正的同时，对教育本身的发展带来了长期的消极的影响。", "Qíndài yǐhòu, jīhū gège cháodài dōu shèlì le zhōngyāng guānxué hé dìfāngguān xué, yǒu zhuānmén dānrèn jiàoshī de guānlì, yǐ rújiā zhùzuò zuòwéi jīběn jiàocái. Búguò, yóuyú cóng suídài yǐhòu zhōngguó shíxíng le kējǔzhìdù, jí tōngguò kǎoshì xuǎnbá guānlì, suǒyǐ, hòulái de guānxué wánquán fúcóng yú kējǔzhìdù, chéng le dāngguān de jiētī. Kējǔzhìdù zài tǐxiàn shèhuì gōngzhèng de tóngshí, duì jiàoyù běnshēn de fāzhǎn dàilái le chángqī de xiāojí de yǐngxiǎng.", "Từ sau đời Tần, hầu như triều đại nào cũng lập quan học trung ương và địa phương, có quan lại chuyên làm thầy, lấy sách Nho gia làm giáo trình cơ bản. Tuy nhiên, vì từ đời Tùy về sau Trung Quốc thực hiện chế độ khoa cử, tức tuyển chọn quan lại qua thi cử, nên quan học về sau hoàn toàn phục tùng khoa cử, trở thành nấc thang để làm quan. Chế độ khoa cử vừa thể hiện sự công bằng xã hội, đồng thời cũng mang lại ảnh hưởng tiêu cực lâu dài cho bản thân sự phát triển của giáo dục."], ["", "西周以前，只有官学，没有私学，所以大多数普通家庭的孩子受教育的机会不多。进入春秋时代，儒学的创始人孔子首开个人讲学之风，提出“有教无类”的主张，不分贵族平民都可以入学。孔子教育思想和教育实践是中国文化、中国教育的宝贵财富，据说弟子达三千人。于是，中国古代产生了新的办学形式——私学。", "Xīzhōu yǐqián, zhǐyǒu guānxué, méiyǒu sīxué, suǒyǐ dàduōshù pǔtōngjiātíng de háizi shòu jiàoyù de jīhuì bù duō. Jìnrù chūnqiūshídài, rúxué de chuàngshǐrén kǒngzi shǒukāi gerén jiǎngxué zhīfēng, tíchū “Yǒujiàowúlèi” de zhǔzhāng, bù fēn guìzú píngmín dōu kěyǐ rùxué. Kǒngzi jiàoyù sīxiǎng hé jiàoyù shíjiàn shì zhōngguó wénhuà, zhōngguó jiàoyù de bǎoguìcáifù, jùshuō dìzǐ dá sānqiān rén. Yúshì, zhōngguó gǔdài chǎnshēng le xīn de bànxué xíngshì—— sīxué.", "Trước Tây Chu chỉ có quan học, không có tư học, nên phần lớn con em gia đình bình thường ít có cơ hội được học. Sang thời Xuân Thu, Khổng Tử – người sáng lập Nho học – mở đầu phong trào dạy học tư nhân, đề ra chủ trương “hữu giáo vô loại”, không phân quý tộc hay bình dân đều được vào học. Tư tưởng và thực tiễn giáo dục của Khổng Tử là tài sản quý của văn hóa, giáo dục Trung Quốc; nghe nói học trò lên tới ba nghìn người. Thế là Trung Quốc cổ đại có một hình thức mở trường mới – tư học."], ["", "书院是中国封建教育的一种特殊形式，历时一千余年，其管理制度及教学方式跟国子监与太学等有很大区别，在教育史上产生过重要的影响。书院开始于唐代，盛行于宋代，被誉为“中华优秀传统文化的重要源头和载体”，有官办和私办两种。", "Shūyuàn shì zhōngguó fēngjiàn jiàoyù de yìzhǒng tèshū xíngshì, lìshí yìqiānyúnián, qí guǎnlǐzhìdù jí jiàoxuéfāngshì gēn guózǐjiàn yǔ tàixué děng yǒu hěndà qūbié, zài jiàoyùshǐ shàng chǎnshēng guò zhòngyào de yǐngxiǎng. Shūyuàn kāishǐ yú tángdài, shèngxíngyú sòngdài, bèiyùwéi “Zhōnghuá yōuxiù chuántǒng wénhuà de zhòngyào yuántóu hé zàitǐ”, yǒu guānbàn hé sībàn liǎngzhǒng.", "Thư viện (thư viện học đường) là một hình thức đặc biệt của giáo dục phong kiến Trung Quốc, kéo dài hơn một nghìn năm, chế độ quản lý và cách dạy khác nhiều với Quốc Tử Giám và Thái học, có ảnh hưởng quan trọng trong lịch sử giáo dục. Thư viện bắt đầu từ đời Đường, thịnh hành đời Tống, được ca ngợi là “nguồn gốc và vật mang quan trọng của văn hóa truyền thống ưu tú Trung Hoa”, có hai loại công lập và tư lập."], ["", "科举制度是封建时代所能采取的最公平的人才选拔形式，它扩展了封建国家引进人才的社会层面，吸收了大量出身中下层社会的人士进入统治阶级。特别是唐宋时期，科举制度之初，显示出生气勃勃的进步性，形成了中国古代文化发展的一个黄金时代。", "Kējǔzhìdù shì fēngjiànshídài suǒ néng cǎiqǔ de zuì gōngpíng de réncái xuǎnbá xíngshì, tā kuòzhǎn le fēngjiàn guójiā yǐnjìnréncái de shèhuì céngmiàn, xīshōu le dàliàng chūshēn zhōngxiàcéng shèhuì de rénshì jìnrù tǒngzhìjiējí. Tèbié shì tángsòng shíqī, kējǔzhìdù zhīchū, xiǎnshì chū shēngqìbóbó de jìnbùxìng, xíngchéng le zhōngguó gǔdài wénhuà fāzhǎn de yíge huángjīnshídài.", "Chế độ khoa cử là hình thức tuyển chọn nhân tài công bằng nhất mà thời phong kiến có thể áp dụng, nó mở rộng tầng lớp xã hội mà nhà nước phong kiến thu nạp nhân tài, đưa nhiều người xuất thân tầng lớp trung và dưới vào giai cấp thống trị. Nhất là thời Đường Tống, buổi đầu chế độ khoa cử thể hiện tính tiến bộ đầy sức sống, tạo nên một thời kỳ hoàng kim của văn hóa cổ đại Trung Quốc."]]}], "fn": [["不但……而且……", "", "Không những… mà còn….", "中国教育不但值得研究，而且也是认识中国需要了解的一个方面。"], ["由……担任", "", "Do… đảm nhiệm.", "教师由国家公务人员担任。"], ["以……作为……", "", "Lấy… làm….", "官学以儒家著作作为基本教材。"], ["在……的同时", "", "Đồng thời với…, trong khi….", "科举制度在体现社会公正的同时，也带来了消极的影响。"], ["被誉为……", "", "Được ca ngợi là….", "书院被誉为“中华优秀传统文化的重要源头”。"]], "adv": [], "ex2": [["为什么各个国家的政府一般都重视教育？", "因为教育关系到人才培养、国民素质和整个社会的发展。", ["因为教育可以赚很多钱。", "因为老师要求政府重视。"]], ["“国学”和“乡学”有什么不同？", "国学设在国都，是中央设立的；乡学设在地方。", ["国学是私人开的，乡学是政府开的。", "国学只教音乐，乡学只教数学。"]], ["科举制度对官学有什么影响？", "官学完全服从于科举，成了当官的阶梯。", ["官学都被取消了。", "官学开始教外语。"]], ["孔子提出了什么教育主张？", "“有教无类”，贵族平民都可以入学。", ["只有贵族可以读书。", "学生必须先考试。"]], ["书院开始于哪个朝代？盛行于哪个朝代？", "开始于唐代，盛行于宋代。", ["开始于清代，盛行于明代。", "开始于汉代，盛行于秦代。"]], ["作者为什么说科举是“最公平的人才选拔形式”？", "它让大量中下层社会的人通过考试进入统治阶级。", ["因为考试题目很简单。", "因为只有皇帝的孩子能参加。"]]]}, "hk4-l13": {"page": "—", "src": "中国国情 · Đất nước học Trung Quốc · Bài 6 中国传统文化", "kw": [{"h": "课文 孔子与儒家", "lines": [["", "公元前551年，孔子出生在鲁国陬邑（今山东曲阜）的一个没落贵族家庭。孔子3岁时，他的父亲就死了，后来母亲也去世了。孔子的少年时代是贫困的，他管理过仓库，也看管过牛羊，这些工作他做得都十分出色。他很喜欢读书，为了将来能为国家出力，他认真地学习礼、乐、射、御、书、数六艺。孔子学习刻苦而又虚心，有不懂的事情就向别人请教。他学习礼，就到很远的洛邑（今洛阳），请教学问很大的老子。他在齐国听到古代音乐的演奏，就专心学习，竟然达到“三月不知肉味”的程度。这样，孔子逐渐成为学问广博的学者。那时候，很多读书人愿拜孔子作老师，于是，孔子就创办了私学。", "Gōngyuánqián551 nián, kǒngzi chūshēng zài lǔguó zōu yì (Jīn shāndōng qūfù) de yíge mòluò guìzú jiātíng. Kǒngzi3 suì shí, tā de fùqīn jiù sǐ le, hòulái mǔqīn yě qùshì le. Kǒngzi de shàoniánshídài shì pínkùn de, tā guǎnlǐ guò cāngkù, yě kānguǎn guò niúyáng, zhèxiē gōngzuò tā zuò dé dōu shífēn chūsè. Tā hěn xǐhuan dúshū, wèile jiānglái néngwèi guójiā chūlì, tā rènzhēn dì xuéxí lǐ, lè, shè, yù, shū, shù liùyì. Kǒngzi xuéxí kèkǔ ér yòu xūxīn, yǒu bù dǒng de shìqing jiù xiàng biérén qǐngjiào. Tā xuéxí lǐ, jiù dào hěn yuǎn de luòyì (Jīn luòyáng), qǐngjiào xuéwen hěndà de lǎozi. Tā zài qíguó tīngdào gǔdài yīnyuè de yǎnzòu, jiù zhuānxīn xuéxí, jìngrán dádào “Sān yuè bù zhī ròu wèi” de chéngdù. Zhèyàng, kǒngzi zhújiàn chéngwéi xuéwen guǎngbó de xuézhě. Nà shíhou, hěnduō dúshūrén yuànbài kǒngzi zuò lǎoshī, yúshì, kǒngzi jiù chuàngbàn le sīxué.", "Năm 551 TCN, Khổng Tử sinh ra trong một gia đình quý tộc sa sút ở ấp Trâu nước Lỗ (nay là Khúc Phụ, Sơn Đông). Năm Khổng Tử 3 tuổi, cha ông mất, sau đó mẹ cũng qua đời. Thời niên thiếu ông nghèo khó, từng trông kho, chăn bò dê, việc nào cũng làm rất tốt. Ông rất thích đọc sách; để sau này góp sức cho đất nước, ông chăm chỉ học sáu nghề lễ, nhạc, xạ, ngự, thư, số. Khổng Tử học hành khắc khổ mà khiêm tốn, có gì không hiểu thì hỏi người khác. Học lễ, ông đến tận Lạc Ấp xa xôi hỏi Lão Tử uyên bác. Ở nước Tề nghe tấu nhạc cổ, ông chuyên tâm học đến mức “ba tháng không biết vị thịt”. Cứ thế Khổng Tử dần thành học giả uyên bác. Khi ấy nhiều người đọc sách muốn bái ông làm thầy, nên ông mở trường tư."], ["", "孔子50岁时在鲁国做了官。他当官时间不长，却把鲁国治理得非常好，表现出较好的政治才能。不久，孔子对昏庸的鲁国国君十分失望，就不做官了，带着他的学生周游各个诸侯国，宣传他的政治主张，希望各国的国君能采用他的意见。可是，他辛辛苦苦奔走了十几年，各国国君都不用他，他只好又回到鲁国，那时他已经68岁了。", "Kǒngzi50 suì shí zài lǔguó zuò le guān. Tā dāngguān shíjiān bù zhǎng, què bǎ lǔguó zhìlǐ dé fēicháng hǎo, biǎoxiàn chūjiào hǎo de zhèngzhì cáinéng. Bùjiǔ, kǒngzi duì hūnyōng de lǔguó guójūn shífēn shīwàng, jiù bú zuòguān le, dài zhe tā de xuéshēng zhōuyóu gège zhūhóuguó, xuānchuán tā de zhèngzhì zhǔzhāng, xīwàng gèguó de guójūn néng cǎiyòng tā de yìjiàn. Kěshì, tā xīnxīnkǔkǔ bēnzǒu le shíjǐnián, gèguó guójūn dōu búyòng tā, tā zhǐhǎo yòu huídào lǔguó, nàshí tā yǐjīng68 suì le.", "Năm 50 tuổi Khổng Tử làm quan ở nước Lỗ. Thời gian làm quan không dài nhưng ông cai trị nước Lỗ rất tốt, thể hiện tài chính trị. Không lâu sau, ông rất thất vọng với vua Lỗ hôn ám, bèn thôi làm quan, dẫn học trò chu du các nước chư hầu, tuyên truyền chủ trương chính trị, mong vua các nước dùng ý kiến của mình. Nhưng ông vất vả bôn ba hơn mười năm, vua các nước đều không dùng ông, đành quay về nước Lỗ, khi ấy ông đã 68 tuổi."], ["", "孔子晚年仍不停地工作，一方面继续讲学，一方面整理古书。据说，他整理了《诗经》《尚书》等几部书，还对鲁国史书《春秋》作了修订。孔子整理古书，对中国古代文化的保存和传播做出了贡献。", "Kǒngzi wǎnnián réng bùtíng dì gōngzuò, yìfāngmiàn jìxù jiǎngxué, yìfāngmiàn zhěnglǐ gǔshū. Jùshuō, tā zhěnglǐ le «Shījīng» «Shàngshū» děng jǐbù shū, hái duì lǔguó shǐshū «Chūnqiū» zuò le xiūdìng. Kǒngzi zhěnglǐ gǔshū, duì zhōngguó gǔdài wénhuà de bǎocún hé chuánbō zuòchū le gòngxiàn.", "Về già Khổng Tử vẫn không ngừng làm việc, một mặt tiếp tục dạy học, một mặt chỉnh lý sách cổ. Nghe nói ông chỉnh lý 《Kinh Thi》, 《Thượng Thư》 và sửa chữa sử nước Lỗ 《Xuân Thu》. Việc chỉnh lý sách cổ của Khổng Tử góp phần lưu giữ và truyền bá văn hóa cổ đại Trung Quốc."], ["", "孔子是中国古代的大思想家和大教育家，他为后代留下了非常丰富的文化思想财富，使他在中国文化史和世界文化史上占有极其重要的位置。", "Kǒngzi shì zhōngguó gǔdài de dà sīxiǎngjiā hé dà jiàoyùjiā, tā wèi hòudài liúxià le fēicháng fēngfù de wénhuà sīxiǎng cáifù, shǐ tā zài zhōngguó wénhuàshǐ hé shìjiè wénhuàshǐ shàng zhànyǒu jíqízhòngyào de wèizhì.", "Khổng Tử là nhà tư tưởng lớn, nhà giáo dục lớn của Trung Quốc cổ đại; ông để lại cho hậu thế tài sản tư tưởng văn hóa vô cùng phong phú, khiến ông giữ vị trí cực kỳ quan trọng trong lịch sử văn hóa Trung Quốc và thế giới."], ["", "儒家又称儒学、孔孟思想、孔儒思想。所谓“儒”，最早是在奴隶主贵族中掌管道德教化、音乐礼仪的官员。后来，这些人在社会变动中逐渐分化，流落到民间。有的为诸侯执掌礼仪，成文“君子儒”；有的则只能替人办理丧葬祭礼，成为“小人儒”。由于这些人熟悉“诗书礼乐”，待人温文尔雅，其学问和道德都高于常人。到孔子出现以后，因其弟子众多，影响扩大，“儒”就成了孔门弟子的专称，由孔子创立的学说称为“儒学”。后经孟子、荀子等人继承和发展，成为春秋战国时代影响最大的思想流派。到汉武帝时代，儒学被推上独尊地位，指导中国社会生活达数千年。至今仍是有一定生命力的学术流派。", "Rújiā yòuchēng rúxué, kǒngmèng sīxiǎng, kǒngrú sīxiǎng. Suǒwèi “Rú”, zuìzǎo shì zài núlìzhǔ guìzú zhōng zhǎngguǎn dàodé jiàohuà, yīnyuè lǐyí de guānyuán. Hòulái, zhèxiē rén zài shèhuì biàndòng zhōng zhújiàn fēnhuà, liúluò dào mínjiān. Yǒu de wèi zhūhóu zhízhǎng lǐyí, chéngwén “Jūnzǐ rú” ; yǒu de zé zhǐnéng tìrén bànlǐ sāngzàng jìlǐ, chéngwéi “Xiǎorén rú”. Yóuyú zhèxiē rén shúxī “Shīshūlǐyuè”, dàirén wēnwéněryǎ, qí xuéwen hé dàodé dōu gāoyú chángrén. Dào kǒngzi chūxiàn yǐhòu, yīn qí dìzǐ zhòngduō, yǐngxiǎng kuòdà, “Rú” jiù chéng le kǒngmén dìzǐ de zhuānchēng, yóu kǒngzi chuànglì de xuéshuō chēngwéi “Rúxué”. Hòujīng mèngzi, xúnzi děng rén jìchéng hé fāzhǎn, chéngwéi chūnqiūzhànguó shídài yǐngxiǎng zuìdà de sīxiǎng liúpài. Dào hànwǔdì shídài, rúxué bèi tuīshàng dúzūn dìwèi, zhǐdǎo zhōngguó shèhuì shēnghuó dá shùqiānnián. Zhìjīn réng shì yǒu yídìng shēngmìnglì de xuéshù liúpài.", "Nho gia còn gọi là Nho học, tư tưởng Khổng Mạnh. Cái gọi là “nho” ban đầu là quan lại trong giới quý tộc chủ nô coi việc giáo hóa đạo đức, âm nhạc lễ nghi. Về sau họ phân hóa trong biến động xã hội, lưu lạc vào dân gian. Vì họ thông thạo “Thi Thư Lễ Nhạc”, đối nhân ôn hòa nho nhã, học vấn và đạo đức đều hơn người thường. Khi Khổng Tử xuất hiện, vì học trò đông, ảnh hưởng rộng, “nho” trở thành tên gọi riêng cho học trò cửa Khổng, học thuyết do Khổng Tử sáng lập gọi là “Nho học”. Sau được Mạnh Tử, Tuân Tử kế thừa và phát triển, trở thành trường phái tư tưởng ảnh hưởng lớn nhất thời Xuân Thu Chiến Quốc. Đến thời Hán Vũ Đế, Nho học được đưa lên địa vị độc tôn, chỉ đạo đời sống xã hội Trung Quốc mấy nghìn năm. Đến nay vẫn là trường phái học thuật còn sức sống nhất định."]]}], "fn": [["为了……", "", "Để… (mục đích).", "为了将来能为国家出力，他认真地学习六艺。"], ["竟然……", "", "Thế mà, lại (ngoài dự đoán).", "他专心学习，竟然达到“三月不知肉味”的程度。"], ["一方面……一方面……", "", "Một mặt… một mặt….", "孔子晚年一方面继续讲学，一方面整理古书。"], ["只好……", "", "Đành phải….", "各国国君都不用他，他只好又回到鲁国。"], ["对……做出贡献", "", "Góp phần vào….", "孔子整理古书，对古代文化的保存做出了贡献。"]], "adv": [], "ex2": [["孔子少年时代的生活怎么样？", "很贫困，管理过仓库，看管过牛羊。", ["非常富有，什么都不用做。", "一直在宫里当官。"]], ["“三月不知肉味”说明了什么？", "孔子学习音乐非常专心。", ["孔子不喜欢吃肉。", "孔子家里没有钱买肉。"]], ["孔子为什么不做官了？", "他对昏庸的鲁国国君十分失望。", ["他年纪太大了。", "他想去做生意。"]], ["孔子晚年做了哪些工作？", "继续讲学，整理《诗经》《尚书》等古书。", ["去国外旅行。", "只在家休息。"]], ["儒学什么时候被推上独尊地位？", "汉武帝时代。", ["唐太宗时代。", "春秋时代。"]]]}, "hk4-l14": {"page": "—", "src": "中国国情 · Đất nước học Trung Quốc · Bài 7  中国传统节日", "kw": [{"h": "课文 中国传统节日", "lines": [["", "春节也就是农历新年正月初一，是民间最古老最隆重的传统节日。中国人把过春节叫“过年”。", "Chūnjié yě jiùshì nónglì xīnnián zhēngyuèchūyī, shì mínjiān zuì gǔlǎo zuì lóngzhòng de chuántǒngjiérì. Zhōngguó rén bǎ guò chūnjié jiào “Guònián”.", "Tết Xuân chính là mồng Một tháng Giêng năm mới âm lịch, là ngày lễ truyền thống cổ xưa và long trọng nhất trong dân gian. Người Trung Quốc gọi ăn Tết là “qua năm”."], ["", "春节是全家团聚的日子。春节前一天的晚上叫“除夕”，就是除旧布新的意思。除夕零点，也就是子时，人们要吃除夕晚上包好的饺子，这就是取“更岁交子”的意思。“交子”就是旧的一年的子时与新的一年的子时相交的时刻。“饺子”的名称就由此得来。除了吃饺子之外还吃年糕、馄饨，取“一年比一年高”和“结束新旧交替的混沌状态”的寓意。", "Chūnjié shì quánjiā tuánjù de rìzi. Chūnjié qiányìtiān de wǎnshang jiào “Chúxī”, jiùshì chújiùbùxīn de yìsi. Chúxī língdiǎn, yě jiùshì zishí, rénmen yào chī chúxī wǎnshang bāohǎo de jiǎozi, zhè jiùshì qǔ “Gèngsuì jiāozi” de yìsi. “Jiāozi” jiùshì jiù de yìnián de zi shí yǔ xīn de yìnián de zi shí xiāngjiāo de shíkè. “Jiǎozi” de míngchēng jiù yóucǐ délái. Chúle chījiǎozi zhīwài hái chī niángāo, húntún, qǔ “Yìnián bǐ yìnián gāo” hé “Jiéshù xīnjiùjiāotì de hùndùn zhuàngtài” de yùyì.", "Tết Xuân là ngày cả nhà đoàn tụ. Tối hôm trước Tết gọi là “trừ tịch”, nghĩa là bỏ cũ đón mới. Đúng nửa đêm trừ tịch, tức giờ Tý, người ta ăn sủi cảo gói từ tối, lấy ý “canh tuế giao tý”. “Giao tý” là thời khắc giờ Tý năm cũ giao với giờ Tý năm mới. Tên “sủi cảo” (饺子) bắt nguồn từ đó. Ngoài sủi cảo còn ăn bánh tổ, hoành thánh, lấy ý “năm sau cao hơn năm trước” và “kết thúc trạng thái hỗn độn giao thời cũ mới”."], ["", "元宵节是在农历正月十五日，是中国继春节之后的第一个重要节日。古代把这一天叫“上元节”，“宵”是夜晚的意思，于是就有了“元宵节”这个名称。元宵节是农历年的第一个月圆之夜，人们有赏灯和吃元宵的习惯。民间俗语说“三十儿的火，十五的灯”“正月十五闹元宵”。因此，元宵节又叫“灯节”。", "Yuánxiāojié shì zài nónglì zhēngyuèshíwǔ rì, shì zhōngguó jì chūnjié zhīhòu de dìyīge zhòngyào jiérì. Gǔdài bǎ zhè yìtiān jiào “Shàngyuánjié”, “Xiāo” shì yèwǎn de yìsi, yúshì jiù yǒu le “Yuánxiāojié” zhège míngchēng. Yuánxiāojié shì nónglìnián de dìyīge yuè yuánzhīyè, rénmen yǒushǎng dēng hé chī yuánxiāo de xíguàn. Mínjiān súyǔshuō “Sānshí ér de huǒ, shíwǔ de dēng” “Zhēngyuèshíwǔ nàoyuánxiāo”. Yīncǐ, yuánxiāojié yòu jiào “Dēngjié”.", "Tết Nguyên Tiêu vào ngày rằm tháng Giêng, là ngày lễ quan trọng đầu tiên sau Tết Xuân. Xưa gọi ngày này là “Thượng Nguyên tiết”, “tiêu” nghĩa là đêm, nên có tên “Nguyên Tiêu”. Đây là đêm trăng tròn đầu tiên của năm âm lịch, người ta có tục ngắm đèn và ăn bánh trôi. Tục ngữ có câu “lửa đêm ba mươi, đèn đêm rằm”, “rằm tháng Giêng náo nhiệt Nguyên Tiêu”. Vì thế Nguyên Tiêu còn gọi là “Tết đèn”."], ["", "端午节，人们喜欢吃粽子。粽子的制作是用竹叶或苇叶把糯米包住，扎成三角形、四角形或其他形状，用线绳扎紧煮食。包粽子也来自中国人民对屈原的崇敬和爱戴。屈原投江以后，人们没有打捞到屈原，为了不让鱼虾损伤屈原的尸体，人们纷纷用竹筒装米扔到江里喂鱼虾，这就是最初的粽子“筒粽”的由来。后来人们用竹叶或苇叶代替竹筒，就慢慢变成今天人们吃的粽子，粽子也不再投入江中，而成为一种传统的节日食品。", "Duānwǔjié, rénmen xǐhuan chī zòngzi. Zòngzi de zhìzuò shì yòng zhúyè huò wěiyè bǎ nuòmǐ bāozhù, zhāchéng sānjiǎoxíng, sìjiǎoxíng huò qítā xíngzhuàng, yòng xiànshéng zhājǐn zhǔshí. Bāo zòngzi yě láizì zhōngguó rénmín duì qūyuán de chóngjìng hé àidài. Qūyuán tóujiāng yǐhòu, rénmen méiyǒu dǎlāodào qūyuán, wèile búràng yúxiā sǔnshāng qūyuán de shītǐ, rénmen fēnfēn yòng zhútǒng zhuāngmǐ rēng dào jiānglǐ wèi yúxiā, zhè jiùshì zuìchū de zòngzi “Tǒng zòng” de yóu lái. Hòulái rénmen yòng zhúyè huò wěiyè dàitì zhútǒng, jiù mànmàn biànchéng jīntiān rénmen chī de zòngzi, zòngzi yě búzài tóurù jiāngzhōng, ér chéngwéi yìzhǒng chuántǒng de jiérì shípǐn.", "Tết Đoan Ngọ người ta thích ăn bánh ú (zòngzi). Bánh làm bằng gạo nếp gói trong lá tre hoặc lá lau, buộc thành hình tam giác, tứ giác, dùng dây buộc chặt rồi luộc. Gói bánh ú cũng bắt nguồn từ lòng kính yêu của nhân dân với Khuất Nguyên. Sau khi Khuất Nguyên trầm mình xuống sông, người ta không vớt được ông; để cá tôm không làm hại thi thể ông, mọi người đổ gạo vào ống tre ném xuống sông cho cá tôm ăn, đó là nguồn gốc của “bánh ống” – chiếc bánh ú đầu tiên. Về sau người ta dùng lá tre, lá lau thay ống tre, dần thành bánh ú ngày nay, và bánh không còn ném xuống sông mà thành món ăn truyền thống ngày lễ."], ["", "中秋节是中国的传统节日。每年农历八月十五日是一年秋季的中期，所以这一天被称为中秋节。中秋节又称“团圆节”，这一天人们仰望明月，盼望家人团聚。远在他乡的游子，也借此寄托对故乡和亲人的思念之情。中秋节自古便有祭月、赏月、吃月饼、玩花灯、赏桂花、饮桂花酒等民俗，流传至今，经久不息。", "Zhōngqiūjié shì zhōngguó de chuántǒngjiérì. Měinián nónglì bāyuè shíwǔrì shì yìnián qiūjì de zhōngqī, suǒyǐ zhè yìtiān bèi chēngwéi zhōngqiūjié. Zhōngqiūjié yòuchēng “Tuányuánjié”, zhè yìtiān rénmen yǎngwàng míngyuè, pànwàng jiārén tuánjù. Yuǎnzàitāxiāng de yóuzi, yě jiècǐ jìtuō duì gùxiāng hé qīnrén de sīniàn zhīqíng. Zhōngqiūjié zìgǔ biàn yǒu jì yuè, shǎngyuè, chī yuèbǐng, wán huādēng, shǎng guìhuā, yǐn guìhuājiǔ děng mínsú, liúchuán zhìjīn, jīngjiǔbùxī.", "Tết Trung Thu là ngày lễ truyền thống của Trung Quốc. Rằm tháng Tám âm lịch là giữa mùa thu, nên ngày này gọi là Trung Thu. Trung Thu còn gọi là “Tết đoàn viên”, hôm ấy người ta ngắm trăng sáng, mong người nhà sum họp. Người con xa quê cũng nhân đó gửi gắm nỗi nhớ quê hương, người thân. Từ xưa Trung Thu đã có tục cúng trăng, ngắm trăng, ăn bánh trung thu, chơi đèn, ngắm hoa quế, uống rượu hoa quế…, lưu truyền đến nay không dứt."], ["", "今天的重阳节，被赋予了新的含义。1989年，中国把每年的九月九日定为老人节，增加了重阳节敬老的内涵。传统与现代巧妙地结合，成为尊老、敬老、爱老、助老的老年人的节日。今日登高赏秋与感恩敬老是当今重阳节活动的两大重要主题。", "Jīntiān de chóngyángjié, bèi fùyǔ le xīn de hányì. 1989 nián, zhōngguó bǎ měinián de jiǔyuèjiǔ rì dìngwèi lǎorénjié, zēngjiā le chóngyángjié jìnglǎo de nèihán. Chuántǒng yǔ xiàndài qiǎomiào dì jiéhé, chéngwéi zūnlǎo, jìnglǎo, àilǎo, zhùlǎo de lǎoniánrén de jiérì. Jīnrì dēnggāo shǎngqiū yǔ gǎnēn jìnglǎo shì dāngjīn chóngyángjié huódòng de liǎngdà zhòngyào zhǔtí.", "Tết Trùng Dương ngày nay được trao thêm ý nghĩa mới. Năm 1989, Trung Quốc lấy ngày mùng 9 tháng 9 hằng năm làm Ngày Người cao tuổi, thêm nội hàm kính lão cho Tết Trùng Dương. Truyền thống và hiện đại kết hợp khéo léo, thành ngày lễ của người già với tinh thần tôn lão, kính lão, yêu lão, giúp lão. Lên cao ngắm thu và tri ân kính lão là hai chủ đề quan trọng của Tết Trùng Dương ngày nay."]]}], "fn": [["把……叫(做)……", "", "Gọi… là….", "中国人把过春节叫“过年”。"], ["除了……之外还……", "", "Ngoài… ra còn….", "除了吃饺子之外，还吃年糕、馄饨。"], ["取……之意 / 取……的意思", "", "Lấy ý….", "这些名称与“团圆”相近，取团圆之意。"], ["为了不让……", "", "Để không cho….", "为了不让鱼虾损伤屈原的尸体，人们把米扔到江里。"], ["无论……都……", "", "Bất luận… đều….", "无论身在何地，心中都有一个共同的愿望。"]], "adv": [], "ex2": [["中国人把过春节叫什么？", "叫“过年”。", ["叫“过节日”。", "叫“元宵”。"]], ["“饺子”这个名称是怎么来的？", "来自“更岁交子”，即新旧两年的子时相交。", ["因为饺子很好吃。", "因为饺子是一个人发明的。"]], ["元宵节为什么又叫“灯节”？", "因为人们有赏灯的习惯，“正月十五闹元宵”。", ["因为那天停电了。", "因为灯笼很便宜。"]], ["最初的粽子是怎么来的？", "人们用竹筒装米扔到江里喂鱼虾，保护屈原的尸体。", ["皇帝命令大家吃粽子。", "人们在山上发现了粽子。"]], ["中秋节为什么又叫“团圆节”？", "人们仰望明月，盼望家人团聚。", ["因为月饼是圆的，很好吃。", "因为那天要去旅游。"]], ["1989年以后，重阳节增加了什么内涵？", "敬老的内涵，九月九日成了老人节。", ["成了儿童节。", "成了教师节。"]]]}, "hk4-l15": {"page": "—", "src": "中国国情 · Đất nước học Trung Quốc · Bài 8  中国文学", "kw": [{"h": "课文 唐诗与明清小说", "lines": [["", "中国文学在唐代进入了一个高峰时期，诗歌发展达到了空前繁荣的阶段。中国是诗的国度，自古以来，中国人就有用诗歌抒情的传统。唐代诗歌数量极大，题材广泛，形式和风格丰富多彩，出现了大量思想性和艺术性完美结合的作品，真正是一个百花齐放的黄金时代。唐代不仅有前代句式自由的诗歌，而且还创造了句式固定整齐的新体诗，这就是律诗和绝句。这种新体诗把中国古代诗歌音节和谐、文字精练的艺术特色推到一个新的高度，成为古代抒情诗的典型形式，至今还特别为人民所喜闻乐见。", "Zhōngguó wénxué zài tángdài jìnrù le yíge gāofēng shíqī, shīgē fāzhǎn dádào le kōngqián fánróng de jiēduàn. Zhōngguó shì shī de guódù, zìgǔyǐlái, zhōngguó rén jiù yǒuyòng shīgē shūqíng de chuántǒng. Tángdài shīgē shùliàng jídà, tícái guǎngfàn, xíngshì hé fēnggé fēngfùduōcǎi, chūxiàn le dàliàng sīxiǎngxìng hé yìshùxìng wánměi jiéhé de zuòpǐn, zhēnzhèng shì yíge bǎihuāqífàng de huángjīnshídài. Tángdài bùjǐn yǒu qiándài jùshì zìyóu de shīgē, érqiě hái chuàngzào le jùshì gùdìng zhěngqí de xīntǐshī, zhè jiùshì lǜshī hé juéjù. Zhèzhǒng xīntǐshī bǎ zhōngguó gǔdài shīgē yīnjié héxié, wénzì jīngliàn de yìshù tèsè tuī dào yíge xīn de gāodù, chéngwéi gǔdài shūqíngshī de diǎnxíng xíngshì, zhìjīn hái tèbié wèi rénmín suǒ xǐwénlèjiàn.", "Văn học Trung Quốc thời Đường bước vào thời kỳ đỉnh cao, thơ ca phát triển đến giai đoạn phồn thịnh chưa từng có. Trung Quốc là đất nước của thơ, từ xưa người Trung Quốc đã có truyền thống dùng thơ để bày tỏ tình cảm. Thơ Đường số lượng rất lớn, đề tài rộng, hình thức và phong cách phong phú, xuất hiện nhiều tác phẩm kết hợp hoàn mỹ tư tưởng và nghệ thuật, thật sự là thời kỳ hoàng kim trăm hoa đua nở. Đời Đường không chỉ có thơ câu tự do của các đời trước mà còn sáng tạo thể thơ mới có câu cố định, chỉnh tề, đó là luật thi và tuyệt cú. Thể thơ mới này đưa đặc sắc nghệ thuật hài hòa âm tiết, tinh luyện ngôn từ lên tầm cao mới, thành hình thức tiêu biểu của thơ trữ tình cổ, đến nay vẫn được nhân dân ưa thích."], ["", "李白（字太白，公元701年—762年），他一生大部分时间生活在唐朝最强盛的时期。李白喜欢游览名山大川，写了大量赞美祖国山河的诗篇，他在《望庐山瀑布》诗中写了庐山瀑布飞泻的壮丽景象。李白的诗气既豪迈奔放，又清新飘逸，而且想象丰富，语言轻快，天真素朴，具有浪漫主义色彩。他一生写了一千多首诗，代表作有《静夜思》、《行路难》、《梦游天姥吟留别》、《蜀道难》、《望庐山瀑布》等，被奉为“诗仙”。", "Lǐbái (Zì tàibái, gōngyuán701 nián—762 nián), tā yìshēng dàbùfèn shíjiān shēnghuó zài tángcháo zuì qiángshèng de shíqī. Lǐbái xǐhuan yóulǎn míngshāndàchuān, xiě le dàliàng zànměi zǔguó shānhé de shīpiān, tā zài «Wàng lúshān pùbù» shīzhōng xiě le lúshān pùbù fēixiè de zhuànglì jǐngxiàng. Lǐbái de shīqì jì háomài bēnfàng, yòu qīngxīn piāoyì, érqiě xiǎngxiàng fēngfù, yǔyán qīngkuài, tiānzhēn sùpiáo, jùyǒu làngmànzhǔyì sècǎi. Tā yìshēng xiě le yìqiānduō shǒushī, dàibiǎozuò yǒu «Jìngyè sī», «Xínglùnán», «Mèngyóu tiānlǎoyín liúbié», «Shǔdàonán», «Wàng lúshān pùbù» děng, bèi fèng wèi “Shīxiān”.", "Lý Bạch (tự Thái Bạch, 701–762), phần lớn cuộc đời sống vào thời Đường thịnh vượng nhất. Ông thích du ngoạn danh sơn đại xuyên, viết nhiều bài ca ngợi núi sông đất nước; trong bài 《Vọng Lư Sơn bộc bố》 ông tả cảnh thác Lư Sơn đổ xuống hùng vĩ. Thơ Lý Bạch vừa hào phóng phóng khoáng, vừa thanh tân phiêu dật, giàu tưởng tượng, ngôn ngữ nhẹ nhàng, hồn nhiên mộc mạc, mang màu sắc lãng mạn. Cả đời ông viết hơn nghìn bài, tiêu biểu có 《Tĩnh dạ tư》, 《Hành lộ nan》, 《Thục đạo nan》…, được tôn là “Thi tiên”."], ["", "杜甫一生写了1400多首诗，他的诗语言精练，感情深沉。因为杜甫的诗反映了当时的历史面貌，所以后人称他的诗为“诗史”。人们热爱杜甫，也称他为“诗圣”。", "Dùfǔ yìshēng xiě le1400 duōshǒu shī, tā de shī yǔyán jīngliàn, gǎnqíng shēnchén. Yīnwèi dùfǔ de shī fǎnyìng le dāngshí de lìshǐ miànmào, suǒyǐ hòu rénchēng tā de shī wèi “Shīshǐ”. Rénmen rèài dùfǔ, yě chēng tā wèi “Shīshèng”.", "Đỗ Phủ cả đời viết hơn 1400 bài thơ, ngôn ngữ tinh luyện, tình cảm sâu lắng. Vì thơ Đỗ Phủ phản ánh diện mạo lịch sử đương thời nên người sau gọi thơ ông là “thi sử”. Người ta yêu quý Đỗ Phủ và cũng gọi ông là “Thi thánh”."], ["", "明清两代是中国古典小说兴盛繁荣的时代，出现了一批优秀的长篇章回小说，还有一大批优秀的短篇小说集。四大文学名著《三国演义》、《水浒传》、《西游记》、《红楼梦》是这一时期的杰出成就。", "Míngqīngliǎngdài shì zhōngguó gǔdiǎnxiǎoshuō xīngshèng fánróng de shídài, chūxiàn le yìpī yōuxiù de chángpiān zhānghuíxiǎoshuō, háiyǒu yídàpī yōuxiù de duǎnpiānxiǎoshuō jí. Sìdà wénxuémíngzhù «Sānguóyǎnyì», «Shuǐhǔzhuàn», «Xīyóujì», «Hónglóumèng» shì zhè yìshíqī de jiéchūchéngjiù.", "Hai đời Minh Thanh là thời kỳ tiểu thuyết cổ điển Trung Quốc hưng thịnh, xuất hiện một loạt tiểu thuyết chương hồi dài xuất sắc và nhiều tập truyện ngắn ưu tú. Bốn danh tác 《Tam quốc diễn nghĩa》, 《Thủy hử》, 《Tây du ký》, 《Hồng lâu mộng》 là thành tựu kiệt xuất của thời kỳ này."], ["", "《西游记》的作者为吴承恩，他在民间流行的唐僧西天取经的故事的基础上创造而成，共有100回。小说记述了唐僧师徒西天取经，经过九九八十一难的曲折历程，最后取回了佛经。《西游记》小说充满了神奇色彩，它最大的特点就是幽默和诙谐，语言轻松活泼，既引人发笑，又意味深长。作品塑造了孙悟空、猪八戒等性格鲜明的人物，其中神通广大、会72种变化的孙悟空是最受人们喜爱的。他的形象实际上反映了人民反抗封建统治、勇于斗争的精神。", "«Xīyóujì» de zuòzhě wèi wúchéngēn, tā zài mínjiān liúxíng de tángsēng xītiān qǔjīng de gùshi de jīchǔ shàng chuàngzào érchéng, gòngyǒu100 huí. Xiǎoshuō jìshù le tángsēng shītú xītiān qǔjīng, jīngguò jiǔ jiǔ bā shí yī nán de qūzhé lìchéng, zuìhòu qǔhuí le fójīng. «Xīyóujì» xiǎoshuō chōngmǎn le shénqí sècǎi, tā zuìdà de tèdiǎn jiùshì yōumò hé huīxié, yǔyán qīngsōng huópō, jì yǐnrén fāxiào, yòu yìwèishēncháng. Zuòpǐn sùzào le sūnwùkōng, zhūbājiè děng xìnggé xiānmíng de rénwù, qízhōng shéntōngguǎngdà, huì72 zhǒng biànhuà de sūnwùkōng shì zuìshòu rénmen xǐài de. Tā de xíngxiàng shíjìshàng fǎnyìng le rénmín fǎnkàng fēngjiàntǒngzhì, yǒngyú dòuzhēng de jīngshén.", "《Tây du ký》 của Ngô Thừa Ân được sáng tác dựa trên truyện dân gian Đường Tăng sang Tây Thiên thỉnh kinh, gồm 100 hồi. Truyện kể thầy trò Đường Tăng đi thỉnh kinh, trải qua chín chín tám mươi mốt kiếp nạn, cuối cùng thỉnh được kinh Phật. Tiểu thuyết đầy màu sắc thần kỳ, đặc điểm lớn nhất là hài hước dí dỏm, ngôn ngữ nhẹ nhàng sinh động, vừa gây cười vừa sâu sắc. Tác phẩm xây dựng các nhân vật cá tính rõ nét như Tôn Ngộ Không, Trư Bát Giới; trong đó Tôn Ngộ Không thần thông quảng đại, biết 72 phép biến hóa được yêu thích nhất. Hình tượng ông thực ra phản ánh tinh thần phản kháng ách thống trị phong kiến, dám đấu tranh của nhân dân."]]}], "fn": [["不仅……而且还……", "", "Không chỉ… mà còn….", "唐代不仅有句式自由的诗歌，而且还创造了新体诗。"], ["为……所……", "", "Được… (bị động văn viết).", "新体诗至今还特别为人民所喜闻乐见。"], ["被奉为……", "", "Được tôn là….", "李白被奉为“诗仙”。"], ["因为……所以……", "", "Vì… nên….", "因为杜甫的诗反映了当时的历史面貌，所以后人称他的诗为“诗史”。"], ["既……又……", "", "Vừa… vừa….", "《西游记》的语言既引人发笑，又意味深长。"]], "adv": [], "ex2": [["唐代创造了什么新体诗？", "律诗和绝句。", ["散文和小说。", "自由诗和儿歌。"]], ["李白的诗有什么特点？", "豪迈奔放，清新飘逸，想象丰富，有浪漫主义色彩。", ["只写社会的黑暗。", "语言很难懂。"]], ["后人为什么称杜甫的诗为“诗史”？", "因为他的诗反映了当时的历史面貌。", ["因为他是历史老师。", "因为他只写了历史书。"]], ["中国四大文学名著是哪四部？", "《三国演义》《水浒传》《西游记》《红楼梦》。", ["《诗经》《论语》《春秋》《史记》。", "《静夜思》《春望》《兵车行》《蜀道难》。"]], ["孙悟空的形象反映了什么？", "人民反抗封建统治、勇于斗争的精神。", ["人们喜欢猴子。", "唐僧很厉害。"]]]}});
})(window.CONTENT);
